                onClick={() => setIsMobileMenuOpen(true)}
                aria-label="Open Menu"
              >
                  <Menu size={24} />
              </button>
        </header>

        <div className="flex-1 overflow-y-auto p-4 md:p-6 bg-slate-950">
            {children}
        </div>
      </main>
    </div>
  );
};

export default function App() {
  return (
    <HashRouter>
      <Routes>
        <Route path="/login" element={<Login />} />

        <Route path="/" element={
          <ProtectedRoute>
            <Layout><Dashboard /></Layout>
          </ProtectedRoute>
        } />

        <Route path="/admin" element={
          <ProtectedRoute allowedRoles={[UserRole.ADMIN]}>
            <Layout><AdminPanel /></Layout>
          </ProtectedRoute>
        } />

        <Route path="/documents" element={
          <ProtectedRoute>
            <Layout><Documents /></Layout>
          </ProtectedRoute>
        } />
      </Routes>
    </HashRouter>
  );
}

export enum UserRole {
  ADMIN = 'ADMIN',
  OPERATOR = 'OPERATOR',
  VIEWER = 'VIEWER'
}

export enum PlanTier {
  BASIC = 'BASIC',
  PRO = 'PRO',
  ENTERPRISE = 'ENTERPRISE'
}

export interface User {
  id: string;
  email: string;
  role: UserRole;
  tenantId: string;
  token: string;
}

export interface Tenant {
  id: string;
  name: string;
  plan: PlanTier;
  maxStreams: number;
  aiEnabled: boolean;
}

export interface CameraStream {
  id: string;
  name: string;
  url: string; // HLS or WebRTC http stream url
  rtspUrl?: string; // Original RTSP source
  status: 'online' | 'offline' | 'error';
  location: string;
  tenantId: string;
}

export interface AnalysisResult {
  detectedObjects: string[];
  threatLevel: 'LOW' | 'MEDIUM' | 'HIGH';
  description?: string;
  licensePlates?: string[];
  facesDetected?: number;
}

export interface SecurityAlert {
  id: string;
  streamId: string;
  timestamp: number;
  type: 'PERSON' | 'VEHICLE' | 'LPR' | 'FACE_MATCH' | 'UNAUTHORIZED';
  severity: 'LOW' | 'MEDIUM' | 'HIGH' | 'CRITICAL';
  description: string;
  thumbnail?: string; // Base64
}

import { GoogleGenAI, Type } from "@google/genai";
import { AnalysisResult } from "../types";

const getClient = () => {
  const apiKey = process.env.API_KEY;
  if (!apiKey) throw new Error("API_KEY not found in environment");
  return new GoogleGenAI({ apiKey });
};

export const analyzeFrame = async (base64Image: string): Promise<AnalysisResult> => {
  try {
    const ai = getClient();
    // Removing the header if present to get raw base64
    const cleanBase64 = base64Image.replace(/^data:image\/(png|jpeg|jpg);base64,/, '');

    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash',
      contents: {
        parts: [
          {
            inlineData: {
              mimeType: 'image/jpeg',
              data: cleanBase64
            }
          },
          {
            text: "Analyze this security camera frame. Identify any persons, vehicles, or potential security threats. If license plates are visible, attempt to read them. Return a JSON object."
          }
        ]
      },
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            detectedObjects: {
              type: Type.ARRAY,
              items: { type: Type.STRING }
            },
            threatLevel: {
              type: Type.STRING,
              enum: ["LOW", "MEDIUM", "HIGH"]
            },
            description: { type: Type.STRING },
            licensePlates: {
              type: Type.ARRAY,
              items: { type: Type.STRING }
            },
            facesDetected: { type: Type.NUMBER }
          }
        }
      }
    });

    const result = JSON.parse(response.text || "{}");
    return result as AnalysisResult;
  } catch (error) {
    console.error("Gemini Analysis Failed:", error);
    // Return a safe fallback to prevent UI crash
    return {
        detectedObjects: [],
        threatLevel: 'LOW',
        description: "Analysis failed due to error."
    };
  }
};

