import React from 'react';
import { HashRouter, Routes, Route } from 'react-router-dom';
import { UserRole } from './types';

// Components
import { Layout } from './components/Layout';
import { ProtectedRoute } from './components/ProtectedRoute';

// Pages
import Dashboard from './pages/Dashboard';
import AdminPanel from './pages/Admin';
import Login from './pages/Login';
import Documents from './pages/Documents';

export default function App() {
  return (
    <HashRouter>
      <Routes>
        <Route path="/login" element={<Login />} />

        <Route path="/" element={
          <ProtectedRoute>
            <Layout><Dashboard /></Layout>
          </ProtectedRoute>
        } />

        <Route path="/admin" element={
          <ProtectedRoute allowedRoles={[UserRole.ADMIN]}>
            <Layout><AdminPanel /></Layout>
          </ProtectedRoute>
        } />

        <Route path="/documents" element={
          <ProtectedRoute>
            <Layout><Documents /></Layout>
          </ProtectedRoute>
        } />
      </Routes>
    </HashRouter>
  );
}

import React, { useRef, useState } from 'react';
import { CameraStream, SecurityAlert } from '../types';
import { analyzeFrame } from '../services/geminiService';
import { AlertTriangle, Eye } from 'lucide-react';

interface StreamPlayerProps {
  stream: CameraStream;
  onAlertGenerated: (alert: SecurityAlert) => void;
}

export const StreamPlayer: React.FC<StreamPlayerProps> = ({ stream, onAlertGenerated }) => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [error, setError] = useState<string | null>(null);

  // Auto-reconnect logic simulation for stream stability
  const handleVideoError = () => {
    setError("Stream offline or format unsupported. Ensure RTSP is transcoded to HLS/WebM.");
  };

  const triggerAnalysis = async () => {
    if (!videoRef.current || !canvasRef.current) return;

    setIsAnalyzing(true);
    try {
      const video = videoRef.current;
      const canvas = canvasRef.current;

      // Set canvas dimensions to match video
      canvas.width = video.videoWidth;
      canvas.height = video.videoHeight;

      // Draw current frame
      const ctx = canvas.getContext('2d');
      if (ctx) {
        ctx.drawImage(video, 0, 0, canvas.width, canvas.height);
        const base64 = canvas.toDataURL('image/jpeg', 0.8);

        const result = await analyzeFrame(base64);

        // Generate alert if threat detected
        if (result.threatLevel === 'HIGH' || result.threatLevel === 'MEDIUM') {
          const newAlert: SecurityAlert = {
            id: crypto.randomUUID(),
            streamId: stream.id,
            timestamp: Date.now(),
            type: result.threatLevel === 'HIGH' ? 'UNAUTHORIZED' : 'VEHICLE',
            severity: result.threatLevel,
            description: result.description || "AI Anomaly Detected",
            thumbnail: base64
          };
          onAlertGenerated(newAlert);
        }
      }
    } catch (e) {
      console.error(e);
    } finally {
      setIsAnalyzing(false);
    }
  };

  return (
    <div className="relative bg-slate-900 rounded-lg overflow-hidden border border-slate-700 group">
      <div className="absolute top-0 left-0 right-0 bg-gradient-to-b from-black/70 to-transparent p-2 z-10 flex justify-between items-center">
        <div className="flex items-center gap-2">
          <span className={`h-2 w-2 rounded-full ${stream.status === 'online' ? 'bg-green-500' : 'bg-red-500'}`}></span>
          <span className="text-xs font-medium text-white">{stream.name}</span>
        </div>
        <div className="flex gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
            <button onClick={triggerAnalysis} disabled={isAnalyzing} className="p-1 bg-blue-600/80 hover:bg-blue-600 rounded text-white" title="Analyze Frame">
                <Eye size={14} />
            </button>
        </div>
      </div>

      {error ? (
        <div className="w-full aspect-video flex flex-col items-center justify-center text-slate-500 bg-black">
          <AlertTriangle className="mb-2" />
          <span className="text-xs text-center px-4">{error}</span>
        </div>
      ) : (
        <video
          ref={videoRef}
          src={stream.url}
          className="w-full aspect-video object-cover bg-black"
          autoPlay
          muted
          loop
          playsInline
          onError={handleVideoError}
        />
      )}

      <canvas ref={canvasRef} className="hidden" />

      {isAnalyzing && (
        <div className="absolute inset-0 flex items-center justify-center bg-black/50 z-20">
           <div className="flex flex-col items-center">
             <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-blue-500 mb-2"></div>
             <span className="text-xs text-blue-200">Analyzing Frame...</span>
           </div>
        </div>
      )}
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { CameraStream } from '../types';
import { Button } from './Button';
import { X, MapPin, Link as LinkIcon, Video } from 'lucide-react';

interface StreamSettingsModalProps {
  isOpen: boolean;
  onClose: () => void;
  onSave: (updatedStream: CameraStream) => void;
  stream: CameraStream | null;
}

export const StreamSettingsModal: React.FC<StreamSettingsModalProps> = ({ 
  isOpen, 
  onClose, 
  onSave, 
  stream 
}) => {
  const [formData, setFormData] = useState<Partial<CameraStream>>({});

  useEffect(() => {
    if (stream) {
      setFormData({
        name: stream.name,
        location: stream.location,
        url: stream.url,
        rtspUrl: stream.rtspUrl
      });
    }
  }, [stream]);

  if (!isOpen || !stream) return null;

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    onSave({ ...stream, ...formData } as CameraStream);
    onClose();
  };

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center p-4">
      {/* Backdrop */}
      <div 
        className="absolute inset-0 bg-black/70 backdrop-blur-sm transition-opacity" 
        onClick={onClose}
