          <h2 className="text-xl font-bold text-white flex items-center gap-2">
            <Video className="text-blue-500" size={24} />
            Configure Stream
          </h2>
          <button 
            onClick={onClose}
            className="text-slate-400 hover:text-white transition-colors p-1 rounded-lg hover:bg-slate-800"
