              />
            </div>
          </div>

          <div>
            <label className="block text-xs font-medium text-slate-400 uppercase mb-1">Stream URL (HLS/MP4)</label>
            <div className="relative">
              <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                <LinkIcon size={16} className="text-slate-600" />
              </div>
              <input
                type="url"
                value={formData.url || ''}
                onChange={(e) => setFormData(prev => ({ ...prev, url: e.target.value }))}
                className="w-full bg-slate-950 border border-slate-800 text-white rounded-lg py-2.5 pl-9 pr-3 focus:outline-none focus:ring-2 focus:ring-blue-600 focus:border-transparent transition-all"
                placeholder="https://..."
                required
              />
            </div>
            <p className="text-[10px] text-slate-500 mt-1">
              Supports HLS (.m3u8) or direct MP4/WebM streams.
            </p>
