import React, { useRef, useState, useEffect } from 'react';
import { CameraStream, SecurityAlert } from '../types';
import { analyzeFrame } from '../services/geminiService';
import { identifyPersonInFrame } from '../services/identityService';
import { AlertTriangle, Eye, Settings, Activity, ShieldCheck, ShieldAlert, UserCheck, UserX } from 'lucide-react';
import Hls from 'hls.js';

interface StreamPlayerProps {
  stream: CameraStream;
  onAlertGenerated: (alert: SecurityAlert) => void;
  onEdit?: () => void;
}

interface StreamError {
    title: string;
    message: string;
    suggestion?: string;
}

export const StreamPlayer: React.FC<StreamPlayerProps> = ({ stream, onAlertGenerated, onEdit }) => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const hlsRef = useRef<Hls | null>(null);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [error, setError] = useState<StreamError | null>(null);
  const [streamType, setStreamType] = useState<'MP4' | 'HLS' | 'RTSP'>('MP4');

  // Auto-Guard State
  const [autoGuard, setAutoGuard] = useState(false);

  // Initialize Stream (HLS or Native)
  useEffect(() => {
    const video = videoRef.current;
    if (!video) return;

    // Reset error state on url change
    setError(null);

    // Detect Stream Type
    if (stream.url.startsWith('rtsp://')) {
        setStreamType('RTSP');
        setError({
            title: "Protocol Unsupported",
            message: "Browsers cannot play raw RTSP streams directly.",
            suggestion: "Use the configuration menu to provision a transcoding backend."
        });
        return;
    } else if (stream.url.endsWith('.m3u8') || stream.url.includes('m3u8')) {
        setStreamType('HLS');
    } else {
        setStreamType('MP4');
    }

    // Cleanup previous HLS instance
    if (hlsRef.current) {
      hlsRef.current.destroy();
      hlsRef.current = null;
    }

    // HLS Implementation
    if (Hls.isSupported() && (stream.url.endsWith('.m3u8') || stream.url.includes('m3u8'))) {
      const hls = new Hls({
        debug: false,
        enableWorker: true,
        lowLatencyMode: true,
        backBufferLength: 90
      });

      hls.loadSource(stream.url);
      hls.attachMedia(video);

      hls.on(Hls.Events.ERROR, (event, data) => {
        if (data.fatal) {
          switch (data.type) {
            case Hls.ErrorTypes.NETWORK_ERROR:
              console.log("fatal network error encountered, try to recover");
              hls.startLoad();
              break;
            case Hls.ErrorTypes.MEDIA_ERROR:
              console.log("fatal media error encountered, try to recover");
              hls.recoverMediaError();
              break;
            default:
              console.log("cannot recover");
              hls.destroy();

              let errTitle = "Stream Connection Failed";
              let errMessage = "A fatal error occurred during playback.";
              let errSuggestion = "Check your network connection and stream URL.";

              if (data.details === 'manifestLoadError') {
                  errTitle = "Manifest Load Error";
                  errMessage = "Unable to load the stream manifest from the server.";
                  errSuggestion = "Ensure the server is online and supports CORS.";
              } else if (data.details === 'manifestParsingError') {
                  errTitle = "Manifest Parsing Error";
                  errMessage = "The stream manifest is invalid or corrupted.";
                  errSuggestion = "Verify the stream source configuration.";
              } else if (data.details === 'levelLoadError') {
                  errTitle = "Segment Load Error";
                  errMessage = "Failed to load video segments.";
                  errSuggestion = "The camera might be offline or experiencing high latency.";
              }

              setError({
                  title: errTitle,
                  message: errMessage,
                  suggestion: errSuggestion
              });
              break;
          }
        }
      });

      hlsRef.current = hls;
    } 
    // Native HLS Support (Safari)
    else if (video.canPlayType('application/vnd.apple.mpegurl')) {
      video.src = stream.url;
    } 
    // Standard playback (MP4/WebM)
    else {
      video.src = stream.url;
    }

    return () => {
      if (hlsRef.current) {
        hlsRef.current.destroy();
      }
    };
  }, [stream.url]);

  const handleVideoError = (e: React.SyntheticEvent<HTMLVideoElement, Event>) => {
    const video = e.currentTarget;
    if (video.error) {
       // Only set error if not already handled by HLS logic
       if (!hlsRef.current) {
          let title = "Playback Error";
          let msg = video.error.message || 'Unknown error occurred';
          let suggestion = "Try refreshing the stream.";

          switch (video.error.code) {
              case 1: // MEDIA_ERR_ABORTED
                  title = "Playback Aborted";
                  msg = "The video playback was aborted.";
                  break;
              case 2: // MEDIA_ERR_NETWORK
                  title = "Network Error";
                  msg = "A network error caused the video download to fail.";
                  suggestion = "Check your internet connection.";
                  break;
              case 3: // MEDIA_ERR_DECODE
                  title = "Decoding Error";
                  msg = "Video data is corrupted or the format is not supported.";
                  suggestion = "The stream encoding (e.g., H.265) might not be supported by this browser.";
                  break;
              case 4: // MEDIA_ERR_SRC_NOT_SUPPORTED
                  title = "Format Not Supported";
                  msg = "The video format or MIME type is not supported.";
                  suggestion = "Ensure the URL points to a valid MP4, WebM, or HLS stream.";
                  break;
          }

          setError({ title, message: msg, suggestion });
       }
    }
  };

  const triggerAnalysis = async (isAutoTrigger = false) => {
    if (!videoRef.current || !canvasRef.current) return;
    if (isAnalyzing) return; // Prevent overlapping requests

    setIsAnalyzing(true);
    try {
      const video = videoRef.current;
      const canvas = canvasRef.current;

      // Set canvas dimensions to match video
      canvas.width = video.videoWidth;
      canvas.height = video.videoHeight;

      // Draw current frame
      const ctx = canvas.getContext('2d');
      if (ctx) {
        ctx.drawImage(video, 0, 0, canvas.width, canvas.height);
        const base64 = canvas.toDataURL('image/jpeg', 0.8);

        // 1. Run Standard Gemini Analysis
        const result = await analyzeFrame(base64);

        let alertGenerated = false;

        // 2. If Persons Detected, Run Identity Check
        if (result.detectedObjects.some(obj => obj.toLowerCase().includes('person') || obj.toLowerCase().includes('face'))) {
             const identityMatch = await identifyPersonInFrame();

             if (identityMatch) {
                 const isBlacklisted = identityMatch.category === 'BLACKLISTED';
                 const newAlert: SecurityAlert = {
                     id: crypto.randomUUID(),
                     streamId: stream.id,
                     timestamp: Date.now(),
                     type: 'FACE_MATCH',
                     severity: isBlacklisted ? 'CRITICAL' : 'LOW',
                     description: isBlacklisted 
                        ? `BLACKLIST MATCH: ${identityMatch.name} detected.` 
                        : `Access Granted: ${identityMatch.name} (${identityMatch.category})`,
                     thumbnail: base64
                 };
                 onAlertGenerated(newAlert);
                 alertGenerated = true;
             }
        }

        // 3. Fallback to Standard Threat Analysis if no identity triggered a Critical alert
        if (!alertGenerated && (result.threatLevel === 'HIGH' || result.threatLevel === 'MEDIUM')) {
          const newAlert: SecurityAlert = {
            id: crypto.randomUUID(),
            streamId: stream.id,
            timestamp: Date.now(),
            type: result.threatLevel === 'HIGH' ? 'UNAUTHORIZED' : 'VEHICLE',
            severity: result.threatLevel,
            description: result.description || "AI Anomaly Detected",
            thumbnail: base64
          };
          onAlertGenerated(newAlert);
        } else if (!isAutoTrigger && !alertGenerated) {
           console.log("Analysis complete: No threats detected.");
        }
      }
    } catch (e) {
      console.error(e);
    } finally {
      setIsAnalyzing(false);
    }
  };

  // Automated Inference Loop
  useEffect(() => {
    if (autoGuard && stream.status === 'online' && !error) {
      // Run analysis every 10 seconds
      const interval = setInterval(() => {
        triggerAnalysis(true);
      }, 10000);
      return () => clearInterval(interval);
    }
  }, [autoGuard, stream.status, error]);

  return (
    <div className={`relative bg-slate-900 rounded-lg overflow-hidden border group h-full transition-colors ${autoGuard ? 'border-blue-500/50 shadow-[0_0_15px_-3px_rgba(59,130,246,0.3)]' : 'border-slate-700'}`}>
      <div className="absolute top-0 left-0 right-0 bg-gradient-to-b from-black/70 to-transparent p-2 z-10 flex justify-between items-center">
        <div className="flex items-center gap-2">
          <span className={`h-2 w-2 rounded-full ${stream.status === 'online' ? 'bg-green-500' : 'bg-red-500'}`}></span>
          <span className="text-xs font-medium text-white shadow-sm">{stream.name}</span>
          {/* Auto-Guard Badge */}
          {autoGuard && (
             <div className="flex items-center gap-1 bg-blue-600/90 text-white text-[9px] px-1.5 py-0.5 rounded font-bold animate-pulse">
                <ShieldCheck size={10} />
                AUTO
             </div>
          )}
        </div>
        <div className="flex gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
            <button
                onClick={() => setAutoGuard(!autoGuard)}
                className={`p-1.5 rounded backdrop-blur-md transition-colors ${autoGuard ? 'bg-blue-600 text-white hover:bg-blue-500' : 'bg-slate-700/80 text-slate-300 hover:bg-slate-600'}`}
                title={autoGuard ? "Disable Auto-Guard" : "Enable Auto-Guard"}
            >
                {autoGuard ? <ShieldCheck size={14} /> : <ShieldAlert size={14} />}
            </button>
            <button 
                onClick={() => triggerAnalysis(false)} 
                disabled={isAnalyzing} 
                className="p-1.5 bg-slate-700/80 hover:bg-slate-600 rounded text-white backdrop-blur-md transition-colors" 
                title="Manual Analysis"
            >
                {isAnalyzing ? <Activity size={14} className="animate-spin" /> : <Eye size={14} />}
            </button>
            {onEdit && (
                <button 
                    onClick={onEdit} 
                    className="p-1.5 bg-slate-700/80 hover:bg-slate-600 rounded text-white backdrop-blur-md transition-colors" 
                    title="Configure Stream"
                >
                    <Settings size={14} />
                </button>
            )}
        </div>
      </div>

      {error ? (
        <div className="w-full h-full flex flex-col items-center justify-center text-slate-500 bg-black p-6 text-center">
          <AlertTriangle className="mb-3 text-red-500 h-8 w-8" />
          <h3 className="text-white font-semibold text-sm mb-1">{error.title}</h3>
          <p className="text-xs text-slate-400 mb-3 max-w-[250px]">{error.message}</p>
          {error.suggestion && (
            <div className="bg-slate-800/50 border border-slate-700 rounded px-3 py-2 max-w-[280px]">
                <p className="text-[10px] text-blue-300">
                    <span className="font-bold mr-1">Tip:</span> 
                    {error.suggestion}
                </p>
            </div>
          )}
        </div>
      ) : (
        <video
          ref={videoRef}
          className="w-full h-full object-cover bg-black"
          autoPlay
          muted
          loop
          playsInline
          onError={handleVideoError}
        />
      )}

      <canvas ref={canvasRef} className="hidden" />

      {isAnalyzing && (
        <div className="absolute inset-0 flex items-center justify-center bg-black/50 z-20 pointer-events-none">
           <div className="flex flex-col items-center animate-in fade-in zoom-in duration-200">
             <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-blue-500 mb-2"></div>
             <span className="text-xs text-blue-200 font-medium">Identifying...</span>
           </div>
        </div>
      )}
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { Users, Plus, Search, Trash2, Edit2, ShieldAlert, UserCheck, User, Briefcase } from 'lucide-react';
import { Button } from '../components/Button';
import { PersonIdentity, IdentityCategory } from '../types';
import { getIdentities, addIdentity, deleteIdentity } from '../services/identityService';

export default function Identities() {
  const [identities, setIdentities] = useState<PersonIdentity[]>([]);
  const [filter, setFilter] = useState('');
  const [showModal, setShowModal] = useState(false);
  const [newPerson, setNewPerson] = useState<Partial<PersonIdentity>>({
      category: 'EMPLOYEE',
      imageUrl: ''
  });

  useEffect(() => {
    loadIdentities();
  }, []);

  const loadIdentities = async () => {
    const data = await getIdentities();
    setIdentities(data);
  };

  const handleAdd = async (e: React.FormEvent) => {
    e.preventDefault();
    if (newPerson.name && newPerson.category) {
        await addIdentity({
            id: crypto.randomUUID(),
            name: newPerson.name,
            category: newPerson.category as IdentityCategory,
            imageUrl: newPerson.imageUrl || 'https://via.placeholder.com/200',
            notes: newPerson.notes
        });
        setShowModal(false);
        setNewPerson({ category: 'EMPLOYEE', imageUrl: '' });
        loadIdentities();
    }
  };

  const handleDelete = async (id: string) => {
      if (confirm('Are you sure you want to remove this identity record?')) {
          await deleteIdentity(id);
          loadIdentities();
      }
  };

  const filteredIdentities = identities.filter(p => 
      p.name.toLowerCase().includes(filter.toLowerCase()) || 
      p.category.toLowerCase().includes(filter.toLowerCase())
  );

  const getCategoryColor = (cat: IdentityCategory) => {
      switch(cat) {
          case 'BLACKLISTED': return 'bg-red-900/50 text-red-200 border-red-800';
          case 'VIP': return 'bg-purple-900/50 text-purple-200 border-purple-800';
          case 'CONTRACTOR': return 'bg-orange-900/50 text-orange-200 border-orange-800';
          default: return 'bg-blue-900/50 text-blue-200 border-blue-800';
      }
  };

  const getCategoryIcon = (cat: IdentityCategory) => {
      switch(cat) {
          case 'BLACKLISTED': return <ShieldAlert size={14} />;
          case 'VIP': return <UserCheck size={14} />;
          case 'CONTRACTOR': return <Briefcase size={14} />;
          default: return <User size={14} />;
      }
  };

  return (
    <div className="h-full flex flex-col space-y-6">
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
        <div>
            <h1 className="text-2xl font-bold text-white flex items-center gap-2">
                <Users className="text-blue-500" />
                Identity Management
            </h1>
            <p className="text-slate-400 text-sm">Manage known personnel, VIPs, and security threats (Watchlist).</p>
        </div>
        <Button onClick={() => setShowModal(true)} className="flex items-center gap-2">
            <Plus size={16} />
            Add Identity
        </Button>
      </div>

      {/* Filter Bar */}
      <div className="bg-slate-900 p-4 rounded-xl border border-slate-800 flex items-center gap-4">
          <Search size={20} className="text-slate-500" />
          <input 
            type="text" 
            placeholder="Search by name or category..." 
            className="bg-transparent border-none focus:outline-none text-white w-full"
            value={filter}
            onChange={e => setFilter(e.target.value)}
          />
      </div>

      {/* Grid */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6 overflow-y-auto pb-6">
          {filteredIdentities.map(person => (
              <div key={person.id} className="bg-slate-900 border border-slate-800 rounded-xl overflow-hidden group hover:border-slate-700 transition-all shadow-lg">
                  <div className="relative h-48 bg-slate-950">
                      <img src={person.imageUrl} alt={person.name} className="w-full h-full object-cover opacity-90 group-hover:opacity-100 transition-opacity" />
                      <div className="absolute inset-0 bg-gradient-to-t from-slate-900 to-transparent"></div>
                      <div className="absolute bottom-4 left-4 right-4">
                          <h3 className="text-lg font-bold text-white truncate">{person.name}</h3>
                          <div className={`inline-flex items-center gap-1.5 px-2 py-0.5 rounded text-xs font-bold border mt-1 ${getCategoryColor(person.category)}`}>
                              {getCategoryIcon(person.category)}
                              {person.category}
                          </div>
                      </div>
                  </div>
                  <div className="p-4 space-y-3">
                      <div className="text-xs text-slate-400">
                          <span className="font-semibold text-slate-500 uppercase block mb-0.5">Notes</span>
                          {person.notes || 'No notes available.'}
                      </div>
                      <div className="text-xs text-slate-400">
                          <span className="font-semibold text-slate-500 uppercase block mb-0.5">Last Seen</span>
                          {person.lastSeen ? new Date(person.lastSeen).toLocaleString() : 'Never'}
                      </div>
                      <div className="pt-2 flex justify-end">
                          <button 
                            onClick={() => handleDelete(person.id)}
                            className="p-2 text-slate-500 hover:text-red-400 hover:bg-red-900/20 rounded transition-colors"
                          >
                              <Trash2 size={16} />
                          </button>
                      </div>
                  </div>
              </div>
          ))}
      </div>

      {/* Add Modal */}
      {showModal && (
          <div className="fixed inset-0 z-[100] flex items-center justify-center p-4">
              <div className="absolute inset-0 bg-black/70 backdrop-blur-sm" onClick={() => setShowModal(false)} />
              <div className="relative bg-slate-900 border border-slate-800 rounded-xl w-full max-w-md shadow-2xl overflow-hidden animate-in fade-in zoom-in duration-200">
                  <div className="p-6 border-b border-slate-800">
                      <h2 className="text-xl font-bold text-white">Enroll New Identity</h2>
                  </div>
                  <form onSubmit={handleAdd} className="p-6 space-y-4">
                      <div>
                          <label className="block text-xs font-medium text-slate-400 uppercase mb-1">Full Name</label>
                          <input 
                             type="text" 
                             className="w-full bg-slate-950 border border-slate-800 rounded-lg px-3 py-2 text-white focus:ring-2 focus:ring-blue-600 outline-none"
                             required
                             value={newPerson.name || ''}
                             onChange={e => setNewPerson({...newPerson, name: e.target.value})}
                          />
                      </div>
                      <div>
                          <label className="block text-xs font-medium text-slate-400 uppercase mb-1">Category</label>
                          <select 
                             className="w-full bg-slate-950 border border-slate-800 rounded-lg px-3 py-2 text-white focus:ring-2 focus:ring-blue-600 outline-none"
                             value={newPerson.category}
                             onChange={e => setNewPerson({...newPerson, category: e.target.value as IdentityCategory})}
                          >
                              <option value="EMPLOYEE">Employee</option>
                              <option value="VIP">VIP</option>
                              <option value="CONTRACTOR">Contractor</option>
                              <option value="BLACKLISTED">Blacklisted (Threat)</option>
                          </select>
                      </div>
                      <div>
                          <label className="block text-xs font-medium text-slate-400 uppercase mb-1">Photo URL</label>
                          <input 
                             type="url" 
                             placeholder="https://..."
                             className="w-full bg-slate-950 border border-slate-800 rounded-lg px-3 py-2 text-white focus:ring-2 focus:ring-blue-600 outline-none"
                             value={newPerson.imageUrl || ''}
                             onChange={e => setNewPerson({...newPerson, imageUrl: e.target.value})}
                          />
                      </div>
                      <div>
                          <label className="block text-xs font-medium text-slate-400 uppercase mb-1">Notes</label>
                          <textarea 
                             className="w-full bg-slate-950 border border-slate-800 rounded-lg px-3 py-2 text-white focus:ring-2 focus:ring-blue-600 outline-none h-20 resize-none"
                             value={newPerson.notes || ''}
                             onChange={e => setNewPerson({...newPerson, notes: e.target.value})}
                          />
                      </div>
                      <div className="flex justify-end gap-3 pt-2">
                          <Button type="button" variant="outline" onClick={() => setShowModal(false)}>Cancel</Button>
                          <Button type="submit">Enroll Identity</Button>
                      </div>
                  </form>
              </div>
          </div>
      )}
    </div>
  );
}

import React, { useState, useEffect, PropsWithChildren } from 'react';
