                    <h2 className="text-xl font-bold text-white">Register Vehicle</h2>
                </div>
                <form onSubmit={handleAddPlate} className="p-6 space-y-4">
                    <div>
                        <label className="block text-xs font-medium text-slate-400 uppercase mb-1">Plate Number</label>
                        <input 
                            type="text" 
                            className="w-full bg-slate-950 border border-slate-800 rounded-lg px-3 py-2 text-white font-mono uppercase focus:ring-2 focus:ring-blue-600 outline-none"
                            required
                            value={newPlate.plateNumber || ''}
                            onChange={e => setNewPlate({...newPlate, plateNumber: e.target.value.toUpperCase()})}
                            placeholder="ABC-1234"
                        />
                    </div>
                    <div>
                        <label className="block text-xs font-medium text-slate-400 uppercase mb-1">Owner Name</label>
                        <input 
                            type="text" 
                            className="w-full bg-slate-950 border border-slate-800 rounded-lg px-3 py-2 text-white focus:ring-2 focus:ring-blue-600 outline-none"
                            value={newPlate.ownerName || ''}
                            onChange={e => setNewPlate({...newPlate, ownerName: e.target.value})}
                        />
                    </div>
                    <div>
                        <label className="block text-xs font-medium text-slate-400 uppercase mb-1">Status</label>
                        <select 
                            className="w-full bg-slate-950 border border-slate-800 rounded-lg px-3 py-2 text-white focus:ring-2 focus:ring-blue-600 outline-none"
                            value={newPlate.status}
                            onChange={e => setNewPlate({...newPlate, status: e.target.value as any})}
                        >
                            <option value="ALLOWED">Allowed (Grant Access)</option>
                            <option value="BLOCKED">Blocked (Deny Access)</option>
                        </select>
                    </div>
                    <div>
                        <label className="block text-xs font-medium text-slate-400 uppercase mb-1">Vehicle Type</label>
                        <input 
                            type="text" 
                            className="w-full bg-slate-950 border border-slate-800 rounded-lg px-3 py-2 text-white focus:ring-2 focus:ring-blue-600 outline-none"
                            value={newPlate.vehicleType || ''}
                            onChange={e => setNewPlate({...newPlate, vehicleType: e.target.value})}
                            placeholder="e.g. Sedan, Truck"
                        />
                    </div>
                    <div className="flex justify-end gap-3 pt-2">
                        <Button type="button" variant="outline" onClick={() => setShowModal(false)}>Cancel</Button>
                        <Button type="submit">Register Plate</Button>
                    </div>
                </form>
            </div>
        </div>
      )}
    </div>
  );
}

import React, { useState, useEffect, PropsWithChildren } from 'react';
import { useLocation, Link } from 'react-router-dom';
import { User, UserRole } from '../types';
import { STORAGE_KEYS } from '../constants';
import { LayoutDashboard, Shield, FileText, LogOut, Menu, X, Search, Users, Car } from 'lucide-react';

interface SidebarItemProps {
  icon: React.ElementType;
  label: string;
  to: string;
  active: boolean;
  onClick?: () => void;
}

const SidebarItem: React.FC<SidebarItemProps> = ({ icon: Icon, label, to, active, onClick }) => (
  <Link 
    to={to} 
    onClick={onClick}
    className={`flex items-center gap-3 px-4 py-3 rounded-lg mb-1 transition-colors ${active ? 'bg-blue-600 text-white' : 'text-slate-400 hover:bg-slate-800 hover:text-white'}`}
  >
    <Icon size={20} />
    <span className="font-medium">{label}</span>
  </Link>
);

export const Layout = ({ children }: PropsWithChildren<{}>) => {
  const location = useLocation();
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);
  const userStr = localStorage.getItem(STORAGE_KEYS.USER);
  const user: User | null = userStr ? JSON.parse(userStr) : null;

  // Close mobile menu when route changes
  useEffect(() => {
    setIsMobileMenuOpen(false);
  }, [location]);

  const handleLogout = () => {
    localStorage.removeItem(STORAGE_KEYS.USER);
    localStorage.removeItem(STORAGE_KEYS.AUTH_TOKEN);
    window.location.hash = '/login';
  };

  return (
    <div className="flex h-screen w-full bg-slate-950 overflow-hidden">
      {/* Mobile Overlay */}
      <div 
        className={`fixed inset-0 bg-black/60 z-[60] md:hidden transition-opacity duration-300 ${isMobileMenuOpen ? 'opacity-100' : 'opacity-0 pointer-events-none'}`}
        onClick={() => setIsMobileMenuOpen(false)}
        aria-hidden="true"
      />

      {/* Sidebar */}
      <aside className={`
        fixed inset-y-0 left-0 z-[70] w-64 bg-slate-900 border-r border-slate-800 flex flex-col 
        transition-transform duration-300 ease-in-out
        md:relative md:translate-x-0
        ${isMobileMenuOpen ? 'translate-x-0' : '-translate-x-full'}
      `}>
        <div className="p-6 border-b border-slate-800 flex justify-between items-center shrink-0">
          <div className="flex items-center gap-2 text-blue-500">
            <Shield size={24} />
            <div className="flex flex-col">
                <span className="text-xl font-bold text-white leading-none">SentinelAI</span>
                <span className="text-[10px] text-slate-400 uppercase tracking-wider font-bold mt-1">
                  {user?.role || 'Guest'} View
                </span>
            </div>
          </div>
          {/* Close button for mobile */}
          <button 
            onClick={() => setIsMobileMenuOpen(false)}
            className="text-slate-400 hover:text-white md:hidden p-1 hover:bg-slate-800 rounded transition-colors"
            aria-label="Close Menu"
          >
            <X size={20} />
          </button>
        </div>

        <nav className="flex-1 p-4 overflow-y-auto">
          <SidebarItem icon={LayoutDashboard} label="Live Monitor" to="/" active={location.pathname === '/'} />
          <SidebarItem icon={Users} label="Identity Management" to="/identities" active={location.pathname === '/identities'} />
          <SidebarItem icon={Car} label="Vehicle Access" to="/access-control" active={location.pathname === '/access-control'} />
          <SidebarItem icon={Search} label="AI Archive Search" to="/search" active={location.pathname === '/search'} />
          {user?.role === UserRole.ADMIN && (
             <SidebarItem icon={Shield} label="Admin Console" to="/admin" active={location.pathname === '/admin'} />
          )}
          <SidebarItem icon={FileText} label="Documents" to="/documents" active={location.pathname === '/documents'} />
        </nav>

        <div className="p-4 border-t border-slate-800 shrink-0">
          <div className="flex items-center gap-3 px-4 py-3 bg-slate-800/50 rounded-lg">
            <div className="w-8 h-8 rounded-full bg-gradient-to-br from-blue-500 to-indigo-600 flex items-center justify-center text-xs font-bold text-white shrink-0">
              {user?.email?.[0]?.toUpperCase() || 'U'}
            </div>
            <div className="flex-1 overflow-hidden">
              <p className="text-sm font-medium text-white truncate" title={user?.email}>{user?.email}</p>
              <p className="text-xs text-slate-500 truncate" title={user?.tenantId}>{user?.tenantId}</p>
            </div>
            <button onClick={handleLogout} className="text-slate-500 hover:text-red-400 transition-colors p-1" title="Logout">
              <LogOut size={18} />
            </button>
          </div>
        </div>
      </aside>

      {/* Main Content */}
      <main className="flex-1 flex flex-col h-full w-full relative overflow-hidden">
        {/* Mobile Header */}
        <header className="md:hidden h-16 bg-slate-900 border-b border-slate-800 flex items-center px-4 justify-between shrink-0 z-50">
             <div className="flex items-center gap-2 text-blue-500">
                <Shield size={24} />
                <span className="text-lg font-bold text-white">SentinelAI</span>
              </div>
              <button 
                className="text-slate-400 hover:text-white p-2 -mr-2"
                onClick={() => setIsMobileMenuOpen(true)}
                aria-label="Open Menu"
              >
                  <Menu size={24} />
              </button>
        </header>

        <div className="flex-1 overflow-y-auto p-4 md:p-6 bg-slate-950">
            {children}
        </div>
      </main>
    </div>
  );
};

import React from 'react';
import { HashRouter, Routes, Route } from 'react-router-dom';
import { UserRole } from './types';

// Components
import { Layout } from './components/Layout';
import { ProtectedRoute } from './components/ProtectedRoute';

// Pages
import Dashboard from './pages/Dashboard';
import AdminPanel from './pages/Admin';
import Login from './pages/Login';
import Documents from './pages/Documents';
import ArchiveSearch from './pages/ArchiveSearch';
import Identities from './pages/Identities';
import AccessControl from './pages/AccessControl';

export default function App() {
  return (
    <HashRouter>
      <Routes>
        <Route path="/login" element={<Login />} />

        <Route path="/" element={
          <ProtectedRoute>
            <Layout><Dashboard /></Layout>
          </ProtectedRoute>
        } />

        <Route path="/identities" element={
          <ProtectedRoute>
            <Layout><Identities /></Layout>
          </ProtectedRoute>
        } />

        <Route path="/access-control" element={
          <ProtectedRoute>
            <Layout><AccessControl /></Layout>
          </ProtectedRoute>
        } />

        <Route path="/search" element={
          <ProtectedRoute>
            <Layout><ArchiveSearch /></Layout>
          </ProtectedRoute>
        } />

        <Route path="/admin" element={
          <ProtectedRoute allowedRoles={[UserRole.ADMIN]}>
            <Layout><AdminPanel /></Layout>
          </ProtectedRoute>
        } />

        <Route path="/documents" element={
          <ProtectedRoute>
            <Layout><Documents /></Layout>
          </ProtectedRoute>
        } />
      </Routes>
    </HashRouter>
  );
}

export enum UserRole {
  ADMIN = 'ADMIN',
  OPERATOR = 'OPERATOR',
  VIEWER = 'VIEWER'
}

export enum PlanTier {
  BASIC = 'BASIC',
  PRO = 'PRO',
  ENTERPRISE = 'ENTERPRISE'
}

export interface User {
  id: string;
  email: string;
  role: UserRole;
  tenantId: string;
  token: string;
}

export interface Tenant {
  id: string;
  name: string;
  plan: PlanTier;
  maxStreams: number;
  aiEnabled: boolean;
}

export interface CameraStream {
  id: string;
  name: string;
  url: string; // HLS or WebRTC http stream url
  rtspUrl?: string; // Original RTSP source
  status: 'online' | 'offline' | 'error';
  location: string;
  tenantId: string;
  // Phase 3: Geospatial
  coordinates?: { x: number; y: number }; // Percentage 0-100 relative to map
  zoneId?: string;
}

export interface MapZone {
    id: string;
    name: string;
    imageUrl: string;
    width: number;
    height: number;
}

export interface AnalysisResult {
  detectedObjects: string[];
  threatLevel: 'LOW' | 'MEDIUM' | 'HIGH';
  description?: string;
  licensePlates?: string[];
  facesDetected?: number;
}

export interface SecurityAlert {
  id: string;
  streamId: string;
  timestamp: number;
  type: 'PERSON' | 'VEHICLE' | 'LPR' | 'FACE_MATCH' | 'UNAUTHORIZED';
  severity: 'LOW' | 'MEDIUM' | 'HIGH' | 'CRITICAL';
  description: string;
  thumbnail?: string; // Base64
}

// Phase 2: Edge Connectivity
export interface IoTDevice {
  id: string;
  name: string;
  type: 'SENSOR_DOOR' | 'SENSOR_MOTION' | 'SENSOR_TEMP' | 'ACCESS_CONTROLLER';
  status: 'active' | 'triggered' | 'idle' | 'offline';
  value?: string | number; // e.g. "21°C" or "OPEN"
  linkedStreamId?: string; // If this sensor triggers, which camera is relevant?
  location: string;
  lastUpdate: number;
}

// Phase 3: Vector Search
export interface ArchiveEvent {
  id: string;
  timestamp: number;
  streamId: string;
  streamName: string;
  description: string;
  confidence: number; // 0-1
  thumbnailUrl: string;
  tags: string[];
}

// Phase 3: Identity Management
export type IdentityCategory = 'EMPLOYEE' | 'VIP' | 'BLACKLISTED' | 'CONTRACTOR';

export interface PersonIdentity {
  id: string;
  name: string;
  category: IdentityCategory;
  imageUrl: string;
  notes?: string;
  lastSeen?: number;
}

// Phase 3: License Plate Recognition (LPR)
export interface PlateRecord {
  plateNumber: string;
  ownerName: string;
  status: 'ALLOWED' | 'BLOCKED' | 'UNKNOWN';
  vehicleType: string; // e.g., "Sedan", "Truck"
  notes?: string;
}

export interface VehicleAccessLog {
  id: string;
  timestamp: number;
  streamId: string;
  plateNumber: string;
  status: 'GRANTED' | 'DENIED' | 'FLAGGED';
  direction: 'ENTRY' | 'EXIT';
  thumbnailUrl?: string; // Base64
  confidence: number;
}

