import React, { useState, useEffect } from 'react';
import { CameraStream } from '../types';
import { Button } from './Button';
import { startTranscodingSession } from '../services/transcodingService';
import { logAction } from '../services/auditService';
import { X, MapPin, Link as LinkIcon, Video, Trash2, Plus, Server, RefreshCw } from 'lucide-react';

interface StreamSettingsModalProps {
  isOpen: boolean;
  onClose: () => void;
  onSave: (updatedStream: CameraStream) => void;
  onDelete: (streamId: string) => void;
  stream: CameraStream | null;
  isNew?: boolean;
}

export const StreamSettingsModal: React.FC<StreamSettingsModalProps> = ({ 
  isOpen, 
  onClose, 
  onSave, 
  onDelete,
  stream,
  isNew = false
}) => {
  const [formData, setFormData] = useState<Partial<CameraStream>>({});
  const [sourceUrl, setSourceUrl] = useState('');
  const [isProvisioning, setIsProvisioning] = useState(false);

  useEffect(() => {
    if (stream) {
      setFormData({
        name: stream.name,
        location: stream.location,
        url: stream.url,
        rtspUrl: stream.rtspUrl
      });
      // Prefer showing the RTSP source if it exists, otherwise the HTTP URL
      setSourceUrl(stream.rtspUrl || stream.url || '');
    }
  }, [stream]);

  if (!isOpen || !stream) return null;

  const isRtsp = sourceUrl.trim().startsWith('rtsp://');

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsProvisioning(true);

    try {
        let finalPlaybackUrl = sourceUrl;
        let finalRtspUrl = undefined;

        if (isRtsp) {
            // Logic: User provided an RTSP URL, we need to "provision" it via the backend
            finalRtspUrl = sourceUrl;
            // Call the mock backend service
            finalPlaybackUrl = await startTranscodingSession(sourceUrl);
        }

        const updatedStream = { 
            ...stream, 
            ...formData, 
            url: finalPlaybackUrl,
            rtspUrl: finalRtspUrl,
            // If it was a new stream, ensure status is online after provisioning
            status: 'online'
        } as CameraStream;

        onSave(updatedStream);

        // Audit Log
        const actionType = isNew ? 'CREATE_STREAM' : 'UPDATE_STREAM';
        await logAction(actionType, `Stream: ${updatedStream.name}`, `Source: ${isRtsp ? 'RTSP' : 'Direct URL'}, Location: ${updatedStream.location}`);

        onClose();
    } catch (error) {
        console.error("Failed to provision stream:", error);
        alert("Failed to connect to RTSP source. Please check the URL and network.");
    } finally {
        setIsProvisioning(false);
    }
  };

  const handleDelete = async () => {
    if (confirm("Are you sure you want to delete this camera stream? This action cannot be undone.")) {
      onDelete(stream.id);
      await logAction('DELETE_STREAM', `Stream: ${stream.name}`, `ID: ${stream.id} removed from tenant.`);
    }
  };

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center p-4">
      {/* Backdrop */}
      <div 
        className="absolute inset-0 bg-black/70 backdrop-blur-sm transition-opacity" 
        onClick={onClose}
      />

      {/* Modal Content */}
      <div className="relative bg-slate-900 border border-slate-800 rounded-xl w-full max-w-lg shadow-2xl overflow-hidden animate-in fade-in zoom-in duration-200">
        <div className="flex justify-between items-center p-6 border-b border-slate-800 bg-slate-900/50">
          <h2 className="text-xl font-bold text-white flex items-center gap-2">
            {isNew ? <Plus className="text-blue-500" size={24} /> : <Video className="text-blue-500" size={24} />}
            {isNew ? 'Add New Stream' : 'Configure Stream'}
          </h2>
          <button 
            onClick={onClose}
            className="text-slate-400 hover:text-white transition-colors p-1 rounded-lg hover:bg-slate-800"
          >
            <X size={20} />
          </button>
        </div>

        <form onSubmit={handleSubmit} className="p-6 space-y-4">
          <div>
            <label className="block text-xs font-medium text-slate-400 uppercase mb-1">Camera Name</label>
            <input
              type="text"
              value={formData.name || ''}
              onChange={(e) => setFormData(prev => ({ ...prev, name: e.target.value }))}
              className="w-full bg-slate-950 border border-slate-800 text-white rounded-lg py-2.5 px-3 focus:outline-none focus:ring-2 focus:ring-blue-600 focus:border-transparent transition-all"
              placeholder="e.g. Main Entrance"
              required
            />
          </div>

          <div>
            <label className="block text-xs font-medium text-slate-400 uppercase mb-1">Location / Zone</label>
            <div className="relative">
              <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                <MapPin size={16} className="text-slate-600" />
              </div>
              <input
                type="text"
                value={formData.location || ''}
                onChange={(e) => setFormData(prev => ({ ...prev, location: e.target.value }))}
                className="w-full bg-slate-950 border border-slate-800 text-white rounded-lg py-2.5 pl-9 pr-3 focus:outline-none focus:ring-2 focus:ring-blue-600 focus:border-transparent transition-all"
                placeholder="e.g. Building A, Lobby"
              />
            </div>
          </div>

          <div>
            <label className="block text-xs font-medium text-slate-400 uppercase mb-1">Source URL</label>
            <div className="relative">
              <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                {isRtsp ? <Server size={16} className="text-purple-500" /> : <LinkIcon size={16} className="text-slate-600" />}
              </div>
              <input
                type="text"
                value={sourceUrl}
                onChange={(e) => setSourceUrl(e.target.value)}
                className={`w-full bg-slate-950 border text-white rounded-lg py-2.5 pl-9 pr-3 focus:outline-none focus:ring-2 focus:ring-blue-600 transition-all ${isRtsp ? 'border-purple-500/50 focus:border-purple-500' : 'border-slate-800 focus:border-transparent'}`}
                placeholder="rtsp://... or https://..."
                required
              />
            </div>
            {isRtsp ? (
                <div className="mt-2 flex items-center gap-2 text-[10px] text-purple-400 bg-purple-900/20 p-2 rounded border border-purple-500/20">
                    <RefreshCw size={12} className="animate-spin-slow" />
                    <span>RTSP detected. Backend transcoder will be provisioned automatically.</span>
                </div>
            ) : (
                <p className="text-[10px] text-slate-500 mt-1">
                  Enter an RTSP stream (will be transcoded) or a direct HLS/MP4 URL.
                </p>
            )}
          </div>

          <div className="flex items-center gap-3 pt-6 mt-2 border-t border-slate-800">
            {!isNew && (
                <Button 
                    type="button" 
                    variant="danger" 
                    onClick={handleDelete}
                    className="flex items-center gap-2"
                    title="Delete Stream"
                    disabled={isProvisioning}
                >
                    <Trash2 size={16} />
                    <span className="hidden sm:inline">Delete</span>
                </Button>
            )}
            <div className="flex-1"></div>
            <Button type="button" variant="outline" onClick={onClose} disabled={isProvisioning}>
              Cancel
            </Button>
            <Button type="submit" variant="primary" isLoading={isProvisioning}>
              {isProvisioning ? 'Provisioning...' : (isNew ? 'Add Stream' : 'Save Changes')}
            </Button>
          </div>
        </form>
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { Users, Plus, Search, Trash2, Edit2, ShieldAlert, UserCheck, User, Briefcase } from 'lucide-react';
import { Button } from '../components/Button';
import { PersonIdentity, IdentityCategory } from '../types';
import { getIdentities, addIdentity, deleteIdentity } from '../services/identityService';
import { logAction } from '../services/auditService';

export default function Identities() {
  const [identities, setIdentities] = useState<PersonIdentity[]>([]);
  const [filter, setFilter] = useState('');
  const [showModal, setShowModal] = useState(false);
  const [newPerson, setNewPerson] = useState<Partial<PersonIdentity>>({
      category: 'EMPLOYEE',
      imageUrl: ''
  });

  useEffect(() => {
    loadIdentities();
  }, []);

  const loadIdentities = async () => {
    const data = await getIdentities();
    setIdentities(data);
  };

  const handleAdd = async (e: React.FormEvent) => {
    e.preventDefault();
    if (newPerson.name && newPerson.category) {
        await addIdentity({
            id: crypto.randomUUID(),
            name: newPerson.name,
            category: newPerson.category as IdentityCategory,
            imageUrl: newPerson.imageUrl || 'https://via.placeholder.com/200',
            notes: newPerson.notes
        });

        await logAction('ADD_IDENTITY', `Person: ${newPerson.name}`, `Category: ${newPerson.category}`);

        setShowModal(false);
        setNewPerson({ category: 'EMPLOYEE', imageUrl: '' });
        loadIdentities();
    }
  };

  const handleDelete = async (id: string, name: string) => {
      if (confirm('Are you sure you want to remove this identity record?')) {
          await deleteIdentity(id);
          await logAction('REMOVE_IDENTITY', `Person: ${name}`, `ID: ${id}`);
          loadIdentities();
      }
  };

  const filteredIdentities = identities.filter(p => 
      p.name.toLowerCase().includes(filter.toLowerCase()) || 
      p.category.toLowerCase().includes(filter.toLowerCase())
  );

  const getCategoryColor = (cat: IdentityCategory) => {
      switch(cat) {
          case 'BLACKLISTED': return 'bg-red-900/50 text-red-200 border-red-800';
          case 'VIP': return 'bg-purple-900/50 text-purple-200 border-purple-800';
          case 'CONTRACTOR': return 'bg-orange-900/50 text-orange-200 border-orange-800';
          default: return 'bg-blue-900/50 text-blue-200 border-blue-800';
      }
  };

  const getCategoryIcon = (cat: IdentityCategory) => {
      switch(cat) {
          case 'BLACKLISTED': return <ShieldAlert size={14} />;
          case 'VIP': return <UserCheck size={14} />;
          case 'CONTRACTOR': return <Briefcase size={14} />;
          default: return <User size={14} />;
      }
  };

  return (
    <div className="h-full flex flex-col space-y-6">
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
        <div>
            <h1 className="text-2xl font-bold text-white flex items-center gap-2">
                <Users className="text-blue-500" />
                Identity Management
            </h1>
            <p className="text-slate-400 text-sm">Manage known personnel, VIPs, and security threats (Watchlist).</p>
        </div>
        <Button onClick={() => setShowModal(true)} className="flex items-center gap-2">
            <Plus size={16} />
            Add Identity
        </Button>
      </div>

      {/* Filter Bar */}
      <div className="bg-slate-900 p-4 rounded-xl border border-slate-800 flex items-center gap-4">
          <Search size={20} className="text-slate-500" />
          <input 
            type="text" 
            placeholder="Search by name or category..." 
            className="bg-transparent border-none focus:outline-none text-white w-full"
            value={filter}
            onChange={e => setFilter(e.target.value)}
          />
      </div>

      {/* Grid */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6 overflow-y-auto pb-6">
          {filteredIdentities.map(person => (
              <div key={person.id} className="bg-slate-900 border border-slate-800 rounded-xl overflow-hidden group hover:border-slate-700 transition-all shadow-lg">
                  <div className="relative h-48 bg-slate-950">
                      <img src={person.imageUrl} alt={person.name} className="w-full h-full object-cover opacity-90 group-hover:opacity-100 transition-opacity" />
                      <div className="absolute inset-0 bg-gradient-to-t from-slate-900 to-transparent"></div>
                      <div className="absolute bottom-4 left-4 right-4">
                          <h3 className="text-lg font-bold text-white truncate">{person.name}</h3>
                          <div className={`inline-flex items-center gap-1.5 px-2 py-0.5 rounded text-xs font-bold border mt-1 ${getCategoryColor(person.category)}`}>
                              {getCategoryIcon(person.category)}
                              {person.category}
                          </div>
                      </div>
                  </div>
                  <div className="p-4 space-y-3">
                      <div className="text-xs text-slate-400">
                          <span className="font-semibold text-slate-500 uppercase block mb-0.5">Notes</span>
                          {person.notes || 'No notes available.'}
                      </div>
                      <div className="text-xs text-slate-400">
                          <span className="font-semibold text-slate-500 uppercase block mb-0.5">Last Seen</span>
                          {person.lastSeen ? new Date(person.lastSeen).toLocaleString() : 'Never'}
                      </div>
                      <div className="pt-2 flex justify-end">
                          <button 
                            onClick={() => handleDelete(person.id, person.name)}
                            className="p-2 text-slate-500 hover:text-red-400 hover:bg-red-900/20 rounded transition-colors"
                          >
                              <Trash2 size={16} />
                          </button>
                      </div>
                  </div>
              </div>
          ))}
      </div>

      {/* Add Modal */}
      {showModal && (
          <div className="fixed inset-0 z-[100] flex items-center justify-center p-4">
              <div className="absolute inset-0 bg-black/70 backdrop-blur-sm" onClick={() => setShowModal(false)} />
              <div className="relative bg-slate-900 border border-slate-800 rounded-xl w-full max-w-md shadow-2xl overflow-hidden animate-in fade-in zoom-in duration-200">
                  <div className="p-6 border-b border-slate-800">
                      <h2 className="text-xl font-bold text-white">Enroll New Identity</h2>
                  </div>
                  <form onSubmit={handleAdd} className="p-6 space-y-4">
                      <div>
                          <label className="block text-xs font-medium text-slate-400 uppercase mb-1">Full Name</label>
                          <input 
                             type="text" 
                             className="w-full bg-slate-950 border border-slate-800 rounded-lg px-3 py-2 text-white focus:ring-2 focus:ring-blue-600 outline-none"
                             required
                             value={newPerson.name || ''}
                             onChange={e => setNewPerson({...newPerson, name: e.target.value})}
                          />
                      </div>
                      <div>
                          <label className="block text-xs font-medium text-slate-400 uppercase mb-1">Category</label>
                          <select 
                             className="w-full bg-slate-950 border border-slate-800 rounded-lg px-3 py-2 text-white focus:ring-2 focus:ring-blue-600 outline-none"
                             value={newPerson.category}
                             onChange={e => setNewPerson({...newPerson, category: e.target.value as IdentityCategory})}
                          >
                              <option value="EMPLOYEE">Employee</option>
                              <option value="VIP">VIP</option>
                              <option value="CONTRACTOR">Contractor</option>
                              <option value="BLACKLISTED">Blacklisted (Threat)</option>
                          </select>
                      </div>
                      <div>
                          <label className="block text-xs font-medium text-slate-400 uppercase mb-1">Photo URL</label>
                          <input 
                             type="url" 
                             placeholder="https://..."
                             className="w-full bg-slate-950 border border-slate-800 rounded-lg px-3 py-2 text-white focus:ring-2 focus:ring-blue-600 outline-none"
                             value={newPerson.imageUrl || ''}
                             onChange={e => setNewPerson({...newPerson, imageUrl: e.target.value})}
                          />
                      </div>
                      <div>
                          <label className="block text-xs font-medium text-slate-400 uppercase mb-1">Notes</label>
                          <textarea 
                             className="w-full bg-slate-950 border border-slate-800 rounded-lg px-3 py-2 text-white focus:ring-2 focus:ring-blue-600 outline-none h-20 resize-none"
                             value={newPerson.notes || ''}
                             onChange={e => setNewPerson({...newPerson, notes: e.target.value})}
                          />
                      </div>
                      <div className="flex justify-end gap-3 pt-2">
                          <Button type="button" variant="outline" onClick={() => setShowModal(false)}>Cancel</Button>
                          <Button type="submit">Enroll Identity</Button>
                      </div>
                  </form>
              </div>
          </div>
      )}
    </div>
  );
}

import React, { useState, useEffect } from 'react';
