// Simulates a backend service (like MediaMTX or go2rtc) that ingests RTSP and outputs HLS/WebRTC
// In a real production env, this would call: POST /api/v1/streams/transcode

const MOCK_HLS_OUTPUTS = [
  'https://test-streams.mux.dev/x36xhzz/x36xhzz.m3u8', // Big Buck Bunny (HLS)
  'https://media.w3.org/2010/05/sintel/trailer.mp4',   // Sintel (MP4)
  'http://commondatastorage.googleapis.com/gtv-videos-bucket/sample/TearsOfSteel.mp4' // Tears of Steel (MP4)
];

// Mock WebRTC (WHEP) endpoints - in a real app these would be wss:// or http://.../whep
const MOCK_WEBRTC_OUTPUTS = [
    'mock-webrtc://stream-01',
    'mock-webrtc://stream-02',
    'mock-webrtc://stream-03'
];

export const startTranscodingSession = async (rtspUrl: string, latencyMode: 'STANDARD' | 'LOW_LATENCY' = 'STANDARD'): Promise<string> => {
  console.log(`[Transcoder] Received request for: ${rtspUrl} [Mode: ${latencyMode}]`);

  // 1. Simulate network latency and container startup time (1.5s - 3s)
  const provisionTime = 1500 + Math.random() * 1500;
  await new Promise(resolve => setTimeout(resolve, provisionTime));

  // 2. Validate format (mock validation)
  if (!rtspUrl.startsWith('rtsp://')) {
    throw new Error("Invalid protocol. Expected rtsp://");
  }

  // 3. Return a deterministic playback URL based on the input length
  const index = rtspUrl.length % 3;

  if (latencyMode === 'LOW_LATENCY') {
      console.log(`[Transcoder] WebRTC (go2rtc) session established.`);
      return MOCK_WEBRTC_OUTPUTS[index];
  } else {
      console.log(`[Transcoder] HLS (ffmpeg) session established.`);
      return MOCK_HLS_OUTPUTS[index];
  }
};

import React, { useState, useEffect } from 'react';
import { CameraStream } from '../types';
import { Button } from './Button';
import { startTranscodingSession } from '../services/transcodingService';
import { logAction } from '../services/auditService';
import { X, MapPin, Link as LinkIcon, Video, Trash2, Plus, Server, RefreshCw, Zap, Clock } from 'lucide-react';

interface StreamSettingsModalProps {
  isOpen: boolean;
  onClose: () => void;
  onSave: (updatedStream: CameraStream) => void;
  onDelete: (streamId: string) => void;
  stream: CameraStream | null;
  isNew?: boolean;
}

export const StreamSettingsModal: React.FC<StreamSettingsModalProps> = ({ 
  isOpen, 
  onClose, 
  onSave, 
  onDelete,
  stream,
  isNew = false
}) => {
  const [formData, setFormData] = useState<Partial<CameraStream>>({});
  const [sourceUrl, setSourceUrl] = useState('');
  const [isProvisioning, setIsProvisioning] = useState(false);

  useEffect(() => {
    if (stream) {
      setFormData({
        name: stream.name,
        location: stream.location,
        url: stream.url,
        rtspUrl: stream.rtspUrl,
        latencyMode: stream.latencyMode || 'STANDARD'
      });
      // Prefer showing the RTSP source if it exists, otherwise the HTTP URL
      setSourceUrl(stream.rtspUrl || stream.url || '');
    }
  }, [stream]);

  if (!isOpen || !stream) return null;

  const isRtsp = sourceUrl.trim().startsWith('rtsp://');

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsProvisioning(true);

    try {
        let finalPlaybackUrl = sourceUrl;
        let finalRtspUrl = undefined;
        const mode = formData.latencyMode || 'STANDARD';

        if (isRtsp) {
            // Logic: User provided an RTSP URL, we need to "provision" it via the backend
            finalRtspUrl = sourceUrl;
            // Call the mock backend service
            finalPlaybackUrl = await startTranscodingSession(sourceUrl, mode);
        }

        const updatedStream = { 
            ...stream, 
            ...formData, 
            url: finalPlaybackUrl,
            rtspUrl: finalRtspUrl,
            // If it was a new stream, ensure status is online after provisioning
            status: 'online'
        } as CameraStream;

        onSave(updatedStream);

        // Audit Log
        const actionType = isNew ? 'CREATE_STREAM' : 'UPDATE_STREAM';
        await logAction(actionType, `Stream: ${updatedStream.name}`, `Source: ${isRtsp ? 'RTSP' : 'Direct URL'}, Mode: ${mode}`);

        onClose();
    } catch (error) {
        console.error("Failed to provision stream:", error);
        alert("Failed to connect to RTSP source. Please check the URL and network.");
    } finally {
        setIsProvisioning(false);
    }
  };

  const handleDelete = async () => {
    if (confirm("Are you sure you want to delete this camera stream? This action cannot be undone.")) {
      onDelete(stream.id);
      await logAction('DELETE_STREAM', `Stream: ${stream.name}`, `ID: ${stream.id} removed from tenant.`);
    }
  };

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center p-4">
      {/* Backdrop */}
      <div 
        className="absolute inset-0 bg-black/70 backdrop-blur-sm transition-opacity" 
        onClick={onClose}
      />

      {/* Modal Content */}
      <div className="relative bg-slate-900 border border-slate-800 rounded-xl w-full max-w-lg shadow-2xl overflow-hidden animate-in fade-in zoom-in duration-200">
        <div className="flex justify-between items-center p-6 border-b border-slate-800 bg-slate-900/50">
          <h2 className="text-xl font-bold text-white flex items-center gap-2">
            {isNew ? <Plus className="text-blue-500" size={24} /> : <Video className="text-blue-500" size={24} />}
            {isNew ? 'Add New Stream' : 'Configure Stream'}
          </h2>
          <button 
            onClick={onClose}
            className="text-slate-400 hover:text-white transition-colors p-1 rounded-lg hover:bg-slate-800"
          >
            <X size={20} />
          </button>
        </div>

        <form onSubmit={handleSubmit} className="p-6 space-y-4">
          <div>
            <label className="block text-xs font-medium text-slate-400 uppercase mb-1">Camera Name</label>
            <input
              type="text"
              value={formData.name || ''}
              onChange={(e) => setFormData(prev => ({ ...prev, name: e.target.value }))}
              className="w-full bg-slate-950 border border-slate-800 text-white rounded-lg py-2.5 px-3 focus:outline-none focus:ring-2 focus:ring-blue-600 focus:border-transparent transition-all"
              placeholder="e.g. Main Entrance"
              required
            />
          </div>

          <div>
            <label className="block text-xs font-medium text-slate-400 uppercase mb-1">Location / Zone</label>
            <div className="relative">
              <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                <MapPin size={16} className="text-slate-600" />
              </div>
              <input
                type="text"
                value={formData.location || ''}
                onChange={(e) => setFormData(prev => ({ ...prev, location: e.target.value }))}
                className="w-full bg-slate-950 border border-slate-800 text-white rounded-lg py-2.5 pl-9 pr-3 focus:outline-none focus:ring-2 focus:ring-blue-600 focus:border-transparent transition-all"
                placeholder="e.g. Building A, Lobby"
              />
            </div>
          </div>

          <div>
            <label className="block text-xs font-medium text-slate-400 uppercase mb-1">Source URL</label>
            <div className="relative">
              <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                {isRtsp ? <Server size={16} className="text-purple-500" /> : <LinkIcon size={16} className="text-slate-600" />}
              </div>
              <input
                type="text"
                value={sourceUrl}
                onChange={(e) => setSourceUrl(e.target.value)}
                className={`w-full bg-slate-950 border text-white rounded-lg py-2.5 pl-9 pr-3 focus:outline-none focus:ring-2 focus:ring-blue-600 transition-all ${isRtsp ? 'border-purple-500/50 focus:border-purple-500' : 'border-slate-800 focus:border-transparent'}`}
                placeholder="rtsp://... or https://..."
                required
              />
            </div>
            {isRtsp ? (
                <div className="mt-2 flex items-center gap-2 text-[10px] text-purple-400 bg-purple-900/20 p-2 rounded border border-purple-500/20">
                    <RefreshCw size={12} className="animate-spin-slow" />
                    <span>RTSP detected. Backend transcoder will be provisioned.</span>
                </div>
            ) : (
                <p className="text-[10px] text-slate-500 mt-1">
                  Enter an RTSP stream (will be transcoded) or a direct HLS/MP4 URL.
                </p>
            )}
          </div>

          {isRtsp && (
              <div>
                  <label className="block text-xs font-medium text-slate-400 uppercase mb-2">Latency Mode</label>
                  <div className="grid grid-cols-2 gap-3">
                      <div 
                        onClick={() => setFormData(prev => ({...prev, latencyMode: 'STANDARD'}))}
                        className={`cursor-pointer rounded-lg border p-3 flex flex-col items-center justify-center text-center gap-2 transition-all ${formData.latencyMode === 'STANDARD' ? 'bg-blue-600/20 border-blue-500 text-blue-400' : 'bg-slate-950 border-slate-800 text-slate-500 hover:border-slate-700'}`}
                      >
                          <Clock size={20} />
                          <div>
                              <div className="text-xs font-bold">Standard (HLS)</div>
                              <div className="text-[10px] opacity-70">10-15s Latency</div>
                          </div>
                      </div>
                      <div 
                        onClick={() => setFormData(prev => ({...prev, latencyMode: 'LOW_LATENCY'}))}
                        className={`cursor-pointer rounded-lg border p-3 flex flex-col items-center justify-center text-center gap-2 transition-all ${formData.latencyMode === 'LOW_LATENCY' ? 'bg-purple-600/20 border-purple-500 text-purple-400' : 'bg-slate-950 border-slate-800 text-slate-500 hover:border-slate-700'}`}
                      >
                          <Zap size={20} />
                          <div>
                              <div className="text-xs font-bold">Ultra Low (WebRTC)</div>
                              <div className="text-[10px] opacity-70">{"< 500ms Latency"}</div>
                          </div>
                      </div>
                  </div>
              </div>
          )}

          <div className="flex items-center gap-3 pt-6 mt-2 border-t border-slate-800">
            {!isNew && (
                <Button 
                    type="button" 
                    variant="danger" 
                    onClick={handleDelete}
                    className="flex items-center gap-2"
                    title="Delete Stream"
                    disabled={isProvisioning}
                >
                    <Trash2 size={16} />
                    <span className="hidden sm:inline">Delete</span>
                </Button>
            )}
            <div className="flex-1"></div>
            <Button type="button" variant="outline" onClick={onClose} disabled={isProvisioning}>
              Cancel
            </Button>
            <Button type="submit" variant="primary" isLoading={isProvisioning}>
              {isProvisioning ? 'Provisioning...' : (isNew ? 'Add Stream' : 'Save Changes')}
            </Button>
          </div>
        </form>
      </div>
    </div>
  );
};

import React, { useRef, useState, useEffect } from 'react';
import { CameraStream, SecurityAlert } from '../types';
import { analyzeFrame } from '../services/geminiService';
import { identifyPersonInFrame } from '../services/identityService';
import { simulatePlateDetection, registerVehicleEntry } from '../services/accessControlService';
import { AlertTriangle, Eye, Settings, Activity, ShieldCheck, ShieldAlert, UserCheck, UserX, Car, Zap, Signal } from 'lucide-react';
import Hls from 'hls.js';

interface StreamPlayerProps {
  stream: CameraStream;
  onAlertGenerated: (alert: SecurityAlert) => void;
  onEdit?: () => void;
}

interface StreamError {
    title: string;
    message: string;
    suggestion?: string;
}

export const StreamPlayer: React.FC<StreamPlayerProps> = ({ stream, onAlertGenerated, onEdit }) => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const hlsRef = useRef<Hls | null>(null);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [error, setError] = useState<StreamError | null>(null);
  const [isWebRTC, setIsWebRTC] = useState(false);
  const [rtcStats, setRtcStats] = useState<{bitrate: string; rtt: string; fps: number}>({ bitrate: '0', rtt: '0', fps: 0 });
  const [connectionState, setConnectionState] = useState<'new'|'connecting'|'connected'|'failed'>('new');

  // Auto-Guard State
  const [autoGuard, setAutoGuard] = useState(false);

  // Initialize Stream (HLS or Native or WebRTC Simulation)
  useEffect(() => {
    const video = videoRef.current;
    if (!video) return;

    // Reset state
    setError(null);
    setConnectionState('new');
    setIsWebRTC(false);

    // Detect Stream Type
    const isMockRTC = stream.url.startsWith('mock-webrtc://');
    const isRealRTSP = stream.url.startsWith('rtsp://');

    if (isRealRTSP) {
        setError({
            title: "Protocol Unsupported",
            message: "Browsers cannot play raw RTSP streams directly.",
            suggestion: "Use the configuration menu to provision a transcoding backend."
        });
        return;
    } 

    if (isMockRTC) {
        setIsWebRTC(true);
        setConnectionState('connecting');

        // Simulate WebRTC Connection establishment
        const connectTimer = setTimeout(() => {
            setConnectionState('connected');
            // Play a real video file to visually simulate the stream, even though protocol is mock
            video.src = 'https://media.w3.org/2010/05/sintel/trailer.mp4';
            video.play().catch(console.error);
        }, 800);

        return () => clearTimeout(connectTimer);
    } 

    // Standard HLS/MP4
    if (hlsRef.current) {
      hlsRef.current.destroy();
      hlsRef.current = null;
    }

    if (Hls.isSupported() && (stream.url.endsWith('.m3u8') || stream.url.includes('m3u8'))) {
      const hls = new Hls({
        debug: false,
        enableWorker: true,
        lowLatencyMode: true,
        backBufferLength: 90
      });

      hls.loadSource(stream.url);
      hls.attachMedia(video);
      hls.on(Hls.Events.ERROR, (event, data) => {
          if (data.fatal) {
              setError({ title: "Stream Error", message: "HLS playback failed.", suggestion: "Check network." });
          }
      });
      hlsRef.current = hls;
    } else {
      video.src = stream.url;
    }

    return () => {
      if (hlsRef.current) hlsRef.current.destroy();
    };
  }, [stream.url]);

  // WebRTC Stats Simulator
  useEffect(() => {
      if (isWebRTC && connectionState === 'connected') {
          const interval = setInterval(() => {
              setRtcStats({
                  bitrate: (2.5 + Math.random() * 0.5).toFixed(1) + ' Mbps',
                  rtt: Math.floor(20 + Math.random() * 15) + ' ms', // 20-35ms RTT (Low Latency)
                  fps: 30
              });
          }, 1000);
          return () => clearInterval(interval);
      }
  }, [isWebRTC, connectionState]);

  const handleVideoError = (e: React.SyntheticEvent<HTMLVideoElement, Event>) => {
    if (!hlsRef.current && !isWebRTC) {
        setError({ title: "Playback Error", message: "Video source failed to load." });
    }
  };

  const triggerAnalysis = async (isAutoTrigger = false) => {
    if (!videoRef.current || !canvasRef.current) return;
    if (isAnalyzing) return;

    setIsAnalyzing(true);
    try {
      const video = videoRef.current;
      const canvas = canvasRef.current;
      canvas.width = video.videoWidth;
      canvas.height = video.videoHeight;
      const ctx = canvas.getContext('2d');
      if (ctx) {
        ctx.drawImage(video, 0, 0, canvas.width, canvas.height);
        const base64 = canvas.toDataURL('image/jpeg', 0.8);

        // 1. Run Gemini Analysis
        const result = await analyzeFrame(base64);
        let alertGenerated = false;

        // 2. Identify Persons
        if (result.detectedObjects.some(obj => obj.toLowerCase().includes('person') || obj.toLowerCase().includes('face'))) {
             const identityMatch = await identifyPersonInFrame();
             if (identityMatch) {
                 const isBlacklisted = identityMatch.category === 'BLACKLISTED';
                 const newAlert: SecurityAlert = {
                     id: crypto.randomUUID(),
                     streamId: stream.id,
                     timestamp: Date.now(),
                     type: 'FACE_MATCH',
                     severity: isBlacklisted ? 'CRITICAL' : 'LOW',
                     description: isBlacklisted 
                        ? `BLACKLIST MATCH: ${identityMatch.name} detected.` 
                        : `Access Granted: ${identityMatch.name} (${identityMatch.category})`,
                     thumbnail: base64
                 };
                 onAlertGenerated(newAlert);
                 alertGenerated = true;
             }
        }

        // 3. Identify Vehicles (LPR)
        if (result.detectedObjects.some(obj => obj.toLowerCase().includes('car') || obj.toLowerCase().includes('vehicle'))) {
            const detectedPlate = await simulatePlateDetection();
            if (detectedPlate) {
                const log = await registerVehicleEntry(stream.id, detectedPlate, base64);
                if (log.status !== 'GRANTED') {
                     const newAlert: SecurityAlert = {
                        id: crypto.randomUUID(),
                        streamId: stream.id,
                        timestamp: Date.now(),
                        type: 'LPR',
                        severity: log.status === 'DENIED' ? 'HIGH' : 'MEDIUM',
                        description: `LPR Alert: Plate ${detectedPlate} is ${log.status}`,
                        thumbnail: base64
                     };
                     onAlertGenerated(newAlert);
                     alertGenerated = true;
                }
            }
        }

        // 4. Fallback
        if (!alertGenerated && (result.threatLevel === 'HIGH' || result.threatLevel === 'MEDIUM')) {
          const newAlert: SecurityAlert = {
            id: crypto.randomUUID(),
            streamId: stream.id,
            timestamp: Date.now(),
            type: result.threatLevel === 'HIGH' ? 'UNAUTHORIZED' : 'VEHICLE',
            severity: result.threatLevel,
            description: result.description || "AI Anomaly Detected",
            thumbnail: base64
          };
          onAlertGenerated(newAlert);
        }
      }
    } catch (e) {
      console.error(e);
    } finally {
      setIsAnalyzing(false);
    }
  };

  useEffect(() => {
    if (autoGuard && stream.status === 'online' && !error) {
      const interval = setInterval(() => triggerAnalysis(true), 10000);
      return () => clearInterval(interval);
    }
  }, [autoGuard, stream.status, error]);

  return (
    <div className={`relative bg-slate-900 rounded-lg overflow-hidden border group h-full transition-colors ${autoGuard ? 'border-blue-500/50 shadow-[0_0_15px_-3px_rgba(59,130,246,0.3)]' : 'border-slate-700'}`}>
      <div className="absolute top-0 left-0 right-0 bg-gradient-to-b from-black/70 to-transparent p-2 z-10 flex justify-between items-center">
        <div className="flex items-center gap-2">
          <span className={`h-2 w-2 rounded-full ${stream.status === 'online' ? 'bg-green-500' : 'bg-red-500'}`}></span>
          <span className="text-xs font-medium text-white shadow-sm">{stream.name}</span>

          {/* Latency Badge */}
          {isWebRTC && connectionState === 'connected' ? (
              <div className="flex items-center gap-1 bg-purple-600/90 text-white text-[9px] px-1.5 py-0.5 rounded font-bold">
                  <Zap size={8} fill="currentColor" />
                  REAL-TIME
              </div>
          ) : !isWebRTC ? (
              <div className="flex items-center gap-1 bg-slate-700/80 text-slate-300 text-[9px] px-1.5 py-0.5 rounded font-bold">
                  LIVE
              </div>
          ) : null}

          {/* Auto-Guard Badge */}
          {autoGuard && (
             <div className="flex items-center gap-1 bg-blue-600/90 text-white text-[9px] px-1.5 py-0.5 rounded font-bold animate-pulse">
                <ShieldCheck size={10} />
                AUTO
             </div>
          )}
        </div>
        <div className="flex gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
            <button
                onClick={() => setAutoGuard(!autoGuard)}
                className={`p-1.5 rounded backdrop-blur-md transition-colors ${autoGuard ? 'bg-blue-600 text-white hover:bg-blue-500' : 'bg-slate-700/80 text-slate-300 hover:bg-slate-600'}`}
                title={autoGuard ? "Disable Auto-Guard" : "Enable Auto-Guard"}
            >
                {autoGuard ? <ShieldCheck size={14} /> : <ShieldAlert size={14} />}
            </button>
            <button 
                onClick={() => triggerAnalysis(false)} 
                disabled={isAnalyzing} 
                className="p-1.5 bg-slate-700/80 hover:bg-slate-600 rounded text-white backdrop-blur-md transition-colors" 
                title="Manual Analysis"
            >
                {isAnalyzing ? <Activity size={14} className="animate-spin" /> : <Eye size={14} />}
            </button>
            {onEdit && (
                <button 
                    onClick={onEdit} 
                    className="p-1.5 bg-slate-700/80 hover:bg-slate-600 rounded text-white backdrop-blur-md transition-colors" 
                    title="Configure Stream"
                >
                    <Settings size={14} />
                </button>
            )}
        </div>
      </div>

      {/* WebRTC Loading State */}
      {isWebRTC && connectionState === 'connecting' && (
          <div className="absolute inset-0 z-0 bg-slate-900 flex flex-col items-center justify-center">
              <div className="flex items-center gap-2 text-purple-400 mb-2">
                  <Signal size={24} className="animate-pulse" />
                  <span className="font-bold">Establishing WebRTC Link...</span>
              </div>
              <div className="text-xs text-slate-500 font-mono">
                  <div>ICE Gathering: Complete</div>
                  <div>DTLS Handshake: Pending...</div>
              </div>
          </div>
      )}

      {error ? (
        <div className="w-full h-full flex flex-col items-center justify-center text-slate-500 bg-black p-6 text-center">
          <AlertTriangle className="mb-3 text-red-500 h-8 w-8" />
          <h3 className="text-white font-semibold text-sm mb-1">{error.title}</h3>
          <p className="text-xs text-slate-400 mb-3 max-w-[250px]">{error.message}</p>
          {error.suggestion && (
            <div className="bg-slate-800/50 border border-slate-700 rounded px-3 py-2 max-w-[280px]">
                <p className="text-[10px] text-blue-300">
                    <span className="font-bold mr-1">Tip:</span> 
                    {error.suggestion}
                </p>
            </div>
          )}
        </div>
      ) : (
        <video
          ref={videoRef}
          className={`w-full h-full object-cover bg-black ${isWebRTC && connectionState !== 'connected' ? 'opacity-0' : 'opacity-100'}`}
          autoPlay
          muted
          loop
          playsInline
          onError={handleVideoError}
        />
      )}

      {/* WebRTC Nerd Stats Overlay */}
      {isWebRTC && connectionState === 'connected' && (
          <div className="absolute bottom-2 left-2 z-10 bg-black/60 backdrop-blur-sm border border-white/10 p-2 rounded text-[9px] font-mono text-white opacity-0 group-hover:opacity-100 transition-opacity pointer-events-none">
              <div className="flex justify-between gap-4">
                  <span className="text-slate-400">Protocol:</span>
                  <span className="text-purple-300">WHEP/WebRTC</span>
              </div>
              <div className="flex justify-between gap-4">
                  <span className="text-slate-400">Bitrate:</span>
                  <span>{rtcStats.bitrate}</span>
              </div>
              <div className="flex justify-between gap-4">
                  <span className="text-slate-400">Latency:</span>
                  <span className="text-green-400">{rtcStats.rtt}</span>
              </div>
              <div className="flex justify-between gap-4">
                  <span className="text-slate-400">FPS:</span>
                  <span>{rtcStats.fps}</span>
              </div>
          </div>
      )}

      <canvas ref={canvasRef} className="hidden" />

      {isAnalyzing && (
        <div className="absolute inset-0 flex items-center justify-center bg-black/50 z-20 pointer-events-none">
           <div className="flex flex-col items-center animate-in fade-in zoom-in duration-200">
             <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-blue-500 mb-2"></div>
             <span className="text-xs text-blue-200 font-medium">Analyzing...</span>
           </div>
        </div>
      )}
    </div>
  );
};

import React, { useState, useMemo, useEffect } from 'react';
import { CameraStream, SecurityAlert, IoTDevice } from '../types';
import { StreamPlayer } from '../components/StreamPlayer';
import { StreamSettingsModal } from '../components/StreamSettingsModal';
import { Bell, Search, Grid, List, Plus, Activity, Thermometer, DoorOpen } from 'lucide-react';
import { Button } from '../components/Button';

// Initial Data
const INITIAL_STREAMS: CameraStream[] = [
  {
    id: '1',
    name: 'Main Entrance (WebRTC)',
    url: 'mock-webrtc://stream-01', // Simulate WebRTC initially
    status: 'online',
    location: 'Building A',
    tenantId: 'tenant-alpha-001',
    latencyMode: 'LOW_LATENCY'
  },
  {
    id: '2',
    name: 'Perimeter HLS',
    // Public HLS Test Stream (Big Buck Bunny) - Validates HLS/H.264 Support
    url: 'https://test-streams.mux.dev/x36xhzz/x36xhzz.m3u8', 
    status: 'online',
    location: 'Exterior',
    tenantId: 'tenant-alpha-001',
    latencyMode: 'STANDARD'
  },
  {
    id: '3',
    name: 'Server Room Hallway',
    url: 'http://commondatastorage.googleapis.com/gtv-videos-bucket/sample/BigBuckBunny.mp4',
    status: 'online',
    location: 'Building B',
    tenantId: 'tenant-alpha-001',
    latencyMode: 'STANDARD'
  },
  {
    id: '4',
    name: 'Loading Dock',
    url: '', // Intentionally empty to show offline state
    status: 'offline',
    location: 'Rear',
    tenantId: 'tenant-alpha-001'
  }
];

// Initial IoT Devices (Phase 2 Edge Connectivity)
const INITIAL_SENSORS: IoTDevice[] = [
  { id: 'iot_1', name: 'Front Door Contact', type: 'SENSOR_DOOR', status: 'idle', value: 'CLOSED', linkedStreamId: '1', location: 'Building A', lastUpdate: Date.now() },
  { id: 'iot_2', name: 'Server Room Temp', type: 'SENSOR_TEMP', status: 'active', value: '21°C', linkedStreamId: '3', location: 'Building B', lastUpdate: Date.now() },
  { id: 'iot_3', name: 'Loading Dock Motion', type: 'SENSOR_MOTION', status: 'idle', value: 'CLEAR', linkedStreamId: '4', location: 'Rear', lastUpdate: Date.now() }
];

export default function Dashboard() {
  const [streams, setStreams] = useState<CameraStream[]>(INITIAL_STREAMS);
  const [alerts, setAlerts] = useState<SecurityAlert[]>([]);
  const [sensors, setSensors] = useState<IoTDevice[]>(INITIAL_SENSORS);
  const [viewMode, setViewMode] = useState<'grid' | 'list'>('grid');
  const [editingStream, setEditingStream] = useState<CameraStream | null>(null);

  // Group consecutive alerts to reduce noise
  const groupedAlerts = useMemo(() => {
    const groups: (SecurityAlert & { count: number })[] = [];
    if (alerts.length === 0) return groups;

    // Start with the newest alert
    let currentGroup = { ...alerts[0], count: 1 };

    for (let i = 1; i < alerts.length; i++) {
      const nextAlert = alerts[i];

      const isSameType = nextAlert.type === currentGroup.type;
      const isSameSeverity = nextAlert.severity === currentGroup.severity;
      const isSameStream = nextAlert.streamId === currentGroup.streamId;

      if (isSameType && isSameSeverity && isSameStream) {
        currentGroup.count++;
      } else {
        groups.push(currentGroup);
        currentGroup = { ...nextAlert, count: 1 };
      }
    }
    groups.push(currentGroup);
    return groups;
  }, [alerts]);

  const handleNewAlert = (alert: SecurityAlert) => {
    setAlerts(prev => [alert, ...prev]);
  };

  const handleSaveStream = (stream: CameraStream) => {
    setStreams(prev => {
        const exists = prev.find(s => s.id === stream.id);
        if (exists) {
            return prev.map(s => s.id === stream.id ? stream : s);
        }
        return [...prev, { ...stream, status: 'online' }]; // Default to online when added
    });
    setEditingStream(null);
  };

  const handleDeleteStream = (streamId: string) => {
    setStreams(prev => prev.filter(s => s.id !== streamId));
    setEditingStream(null);
  };

  const handleAddStream = () => {
    const newStreamTemplate: CameraStream = {
        id: crypto.randomUUID(),
        name: '',
        url: '',
        status: 'offline',
        location: '',
        tenantId: 'tenant-alpha-001',
        latencyMode: 'STANDARD'
    };
    setEditingStream(newStreamTemplate);
  };

  // Simulate IoT Data Stream (Phase 2 Edge Connectivity)
  useEffect(() => {
    const interval = setInterval(() => {
        setSensors(prev => prev.map(sensor => {
            // Randomly flip sensor states
            if (Math.random() > 0.9) {
                if (sensor.type === 'SENSOR_DOOR') {
                    const isOpen = sensor.value === 'CLOSED';
                    return { 
                        ...sensor, 
                        value: isOpen ? 'OPEN' : 'CLOSED', 
                        status: isOpen ? 'triggered' : 'idle',
                        lastUpdate: Date.now()
                    };
                } else if (sensor.type === 'SENSOR_MOTION') {
                    const isMotion = sensor.value === 'CLEAR';
                    return {
                         ...sensor,
                         value: isMotion ? 'DETECTED' : 'CLEAR',
                         status: isMotion ? 'triggered' : 'idle',
                         lastUpdate: Date.now()
                    };
                } else if (sensor.type === 'SENSOR_TEMP') {
                    return { ...sensor, value: (20 + Math.random() * 3).toFixed(1) + '°C', lastUpdate: Date.now() };
                }
            }
            return sensor;
        }));
    }, 3000);
    return () => clearInterval(interval);
  }, []);

  // Determine if the current editing stream is a new one (not in the list yet)
  const isNewStream = editingStream && !streams.some(s => s.id === editingStream.id);

  return (
    <div className="flex flex-col h-full gap-6">
      <StreamSettingsModal 
        isOpen={!!editingStream}
        stream={editingStream}
        isNew={!!isNewStream}
        onClose={() => setEditingStream(null)}
        onSave={handleSaveStream}
        onDelete={handleDeleteStream}
      />

      {/* Top Stats / Controls */}
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h1 className="text-2xl font-bold text-white">Live Monitoring</h1>
          <p className="text-slate-400 text-sm">Tenant Alpha / {streams.length} Active Streams</p>
        </div>

        <div className="flex items-center gap-3">
          <Button variant="secondary" onClick={handleAddStream} className="hidden md:flex items-center gap-2">
            <Plus size={16} />
            <span>Add Stream</span>
          </Button>

          <div className="bg-slate-800 flex items-center rounded-lg px-3 py-2 border border-slate-700">
            <Search size={18} className="text-slate-500 mr-2" />
            <input type="text" placeholder="Search cameras..." className="bg-transparent border-none text-sm text-white focus:outline-none w-32 lg:w-48" />
          </div>

          <div className="flex bg-slate-800 rounded-lg p-1 border border-slate-700">
            <button 
              onClick={() => setViewMode('grid')}
              className={`p-2 rounded ${viewMode === 'grid' ? 'bg-slate-700 text-white' : 'text-slate-400 hover:text-white'}`}
            >
              <Grid size={18} />
            </button>
            <button 
              onClick={() => setViewMode('list')}
              className={`p-2 rounded ${viewMode === 'list' ? 'bg-slate-700 text-white' : 'text-slate-400 hover:text-white'}`}
            >
              <List size={18} />
            </button>
          </div>
        </div>
      </div>

      <div className="flex flex-col lg:flex-row gap-6 flex-1 min-h-0">
        {/* Video Grid */}
        <div className={`flex-1 overflow-y-auto ${viewMode === 'grid' ? 'grid grid-cols-1 md:grid-cols-2 xl:grid-cols-2 gap-4' : 'flex flex-col gap-4'} pr-2`}>
          {streams.length === 0 ? (
             <div className="col-span-full h-64 flex flex-col items-center justify-center border-2 border-dashed border-slate-800 rounded-xl text-slate-500">
                <p>No streams active.</p>
                <Button variant="outline" onClick={handleAddStream} className="mt-4">Add Camera</Button>
             </div>
          ) : (
            streams.map(stream => (
                <div key={stream.id} className={`${viewMode === 'list' ? 'h-64' : 'aspect-video'} relative`}>
                    <StreamPlayer 
                        stream={stream} 
                        onAlertGenerated={handleNewAlert} 
                        onEdit={() => setEditingStream(stream)}
                    />
                    {/* Visual Overlay if linked sensor is triggered */}
                    {sensors.find(s => s.linkedStreamId === stream.id && s.status === 'triggered') && (
                        <div className="absolute bottom-14 left-4 z-20 bg-red-600/90 text-white text-xs px-2 py-1 rounded animate-pulse border border-red-500 shadow-lg font-bold flex items-center gap-1">
                            <Activity size={12} />
                            {sensors.find(s => s.linkedStreamId === stream.id && s.status === 'triggered')?.value}
                        </div>
                    )}
                </div>
            ))
          )}
        </div>

        {/* Sidebar: Alerts & Sensors */}
        <div className="w-full lg:w-72 flex flex-col gap-4">
            {/* Sensor Widget (IoT / Edge Connectivity) */}
            <div className="bg-slate-900 border border-slate-800 rounded-xl overflow-hidden shadow-sm">
                <div className="p-3 border-b border-slate-800 flex items-center justify-between bg-slate-900">
                    <h3 className="text-xs font-semibold text-slate-300 uppercase tracking-wider flex items-center gap-2">
                        <Activity size={14} className="text-green-500" />
                        IoT Sensors
                    </h3>
                    <div className="flex gap-1">
                        <span className="w-2 h-2 rounded-full bg-green-500 animate-pulse"></span>
                    </div>
                </div>
                <div className="p-3 space-y-2">
                    {sensors.map(sensor => (
                        <div key={sensor.id} className="flex items-center justify-between text-sm bg-slate-800/30 p-2 rounded border border-slate-800">
                            <div className="flex items-center gap-2">
                                {sensor.type === 'SENSOR_TEMP' ? <Thermometer size={14} className="text-slate-400" /> : <DoorOpen size={14} className="text-slate-400" />}
                                <span className="text-slate-300 truncate max-w-[100px]" title={sensor.name}>{sensor.name}</span>
                            </div>
                            <span className={`font-mono text-xs font-bold px-1.5 py-0.5 rounded ${
                                sensor.status === 'triggered' ? 'bg-red-500/20 text-red-400 border border-red-500/30' : 
                                sensor.status === 'active' ? 'bg-blue-500/20 text-blue-400' :
                                'text-slate-500'
                            }`}>
                                {sensor.value}
                            </span>
                        </div>
                    ))}
                </div>
            </div>

            {/* Live Alerts */}
            <div className="bg-slate-900 border border-slate-800 rounded-xl flex flex-col overflow-hidden h-72 lg:h-auto flex-1">
                <div className="p-3 border-b border-slate-800 flex items-center justify-between bg-slate-900">
                    <h3 className="text-sm font-semibold text-white flex items-center gap-2">
                    <Bell size={16} className="text-blue-500" />
                    Live Alerts
                    </h3>
                    <span className="text-[10px] bg-blue-900 text-blue-200 px-1.5 py-0.5 rounded-full">{alerts.length}</span>
                </div>

                <div className="flex-1 overflow-y-auto p-3 space-y-2">
                    {groupedAlerts.length === 0 ? (
                    <div className="text-center text-slate-500 py-8 text-xs">
                        System Secure.<br/>No active threats.
                    </div>
                    ) : (
                    groupedAlerts.map(alert => (
                        <div key={alert.id} className="bg-slate-800/50 rounded-lg p-2 border border-slate-700/50 hover:border-slate-600 transition-colors flex gap-2.5 group">
                        {alert.thumbnail && (
                            <div className="relative shrink-0">
                                <img src={alert.thumbnail} alt="Evidence" className="w-16 h-16 object-cover rounded bg-black" />
                                <div className="absolute inset-0 ring-1 ring-inset ring-white/10 rounded pointer-events-none"></div>
                                {alert.count > 1 && (
                                    <div className="absolute -top-1 -right-1 bg-red-500 text-white text-[9px] font-bold px-1.5 py-0.5 rounded-full shadow-sm border border-slate-900">
                                        {alert.count > 99 ? '99+' : `x${alert.count}`}
                                    </div>
                                )}
                            </div>
                        )}
                        <div className="flex-1 min-w-0 flex flex-col justify-center">
                            <div className="flex justify-between items-start mb-1">
                                <div className="flex items-center gap-1.5">
                                    <span className={`px-1.5 py-px rounded-[3px] text-[9px] font-bold uppercase tracking-wider ${
                                        alert.severity === 'CRITICAL' ? 'bg-red-500/20 text-red-200 border border-red-500/30' :
                                        alert.severity === 'HIGH' ? 'bg-orange-500/20 text-orange-200 border border-orange-500/30' :
                                        'bg-blue-500/20 text-blue-200 border border-blue-500/30'
                                    }`}>
                                        {alert.type.replace('_', ' ')}
                                    </span>
                                </div>
                                <span className="text-[10px] text-slate-500 whitespace-nowrap ml-1">
                                    {new Date(alert.timestamp).toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'})}
                                </span>
                            </div>
                            <p className="text-xs text-slate-300 line-clamp-2 leading-tight" title={alert.description}>
                                {alert.description}
                            </p>
                        </div>
                        </div>
                    ))
                    )}
                </div>
            </div>
        </div>
      </div>
    </div>
  );
}

export enum UserRole {
  ADMIN = 'ADMIN',
  OPERATOR = 'OPERATOR',
  VIEWER = 'VIEWER'
}

export enum PlanTier {
  BASIC = 'BASIC',
  PRO = 'PRO',
  ENTERPRISE = 'ENTERPRISE'
}

export interface User {
  id: string;
  email: string;
  role: UserRole;
  tenantId: string;
  token: string;
}

export interface Tenant {
  id: string;
  name: string;
  plan: PlanTier;
  maxStreams: number;
  aiEnabled: boolean;
}

export interface CameraStream {
  id: string;
  name: string;
  url: string; // HLS or WebRTC http stream url
  rtspUrl?: string; // Original RTSP source
  status: 'online' | 'offline' | 'error';
  location: string;
  tenantId: string;
  // Phase 3: Geospatial
  coordinates?: { x: number; y: number }; // Percentage 0-100 relative to map
  zoneId?: string;
  // Phase 4: WebRTC
  latencyMode?: 'STANDARD' | 'LOW_LATENCY';
}

export interface MapZone {
    id: string;
    name: string;
    imageUrl: string;
    width: number;
    height: number;
}

export interface AnalysisResult {
  detectedObjects: string[];
  threatLevel: 'LOW' | 'MEDIUM' | 'HIGH';
  description?: string;
  licensePlates?: string[];
  facesDetected?: number;
}

export interface SecurityAlert {
  id: string;
  streamId: string;
  timestamp: number;
  type: 'PERSON' | 'VEHICLE' | 'LPR' | 'FACE_MATCH' | 'UNAUTHORIZED';
  severity: 'LOW' | 'MEDIUM' | 'HIGH' | 'CRITICAL';
  description: string;
  thumbnail?: string; // Base64
}

// Phase 2: Edge Connectivity
export interface IoTDevice {
  id: string;
  name: string;
  type: 'SENSOR_DOOR' | 'SENSOR_MOTION' | 'SENSOR_TEMP' | 'ACCESS_CONTROLLER';
  status: 'active' | 'triggered' | 'idle' | 'offline';
  value?: string | number; // e.g. "21°C" or "OPEN"
  linkedStreamId?: string; // If this sensor triggers, which camera is relevant?
  location: string;
