export default function Analytics() {
  const [insights, setInsights] = useState<PredictiveInsight[]>([]);
  const [reports, setReports] = useState<SecurityReport[]>([]);
  const [isGenerating, setIsGenerating] = useState(false);

  useEffect(() => {
    loadData();
  }, []);

  const loadData = async () => {
    const insightsData = await getPredictiveInsights();
    const reportsData = await getReports();
    setInsights(insightsData);
    setReports(reportsData);
  };

  const handleGenerateReport = async () => {
      setIsGenerating(true);
      const newRep = await generateReport('WEEKLY_SUMMARY');
      setReports(prev => [newRep, ...prev]);

      setTimeout(() => {
          setReports(prev => prev.map(r => r.id === newRep.id ? {...r, status: 'READY', downloadUrl: '#'} : r));
          setIsGenerating(false);
      }, 3000);
  };

  const getRiskColor = (prob: number) => {
      if (prob >= 80) return 'text-red-500';
      if (prob >= 50) return 'text-orange-500';
      return 'text-blue-500';
  };

  const getTrendIcon = (trend: string) => {
      switch(trend) {
          case 'UP': return <ArrowUpRight size={16} className="text-red-500" />;
          case 'DOWN': return <ArrowDownRight size={16} className="text-green-500" />;
          default: return <Minus size={16} className="text-slate-500" />;
      }
  };

  return (
    <div className="h-full flex flex-col space-y-6">
      <PageHeader 
        title="Predictive Analytics"
        description="AI-driven behavioral analysis and future threat forecasting."
        icon={TrendingUp}
      />

      {/* Top Cards */}
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
          <Card>
              <h3 className="text-sm text-slate-400 font-semibold uppercase mb-4">Overall Threat Forecast</h3>
              <div className="flex items-end gap-3">
                  <span className="text-4xl font-bold text-white">Low</span>
                  <span className="text-green-500 font-medium mb-1 flex items-center gap-1">
                      <ArrowDownRight size={16} /> -12% vs last week
                  </span>
              </div>
              <div className="mt-4 h-2 bg-slate-800 rounded-full overflow-hidden">
                  <div className="h-full w-[25%] bg-green-500"></div>
              </div>
          </Card>

          <Card>
              <h3 className="text-sm text-slate-400 font-semibold uppercase mb-4">Projected Incidents (24h)</h3>
              <div className="flex items-end gap-3">
                  <span className="text-4xl font-bold text-white">3</span>
                  <span className="text-orange-500 font-medium mb-1 flex items-center gap-1">
                      <ArrowUpRight size={16} /> Loitering High
                  </span>
              </div>
               <div className="mt-4 h-2 bg-slate-800 rounded-full overflow-hidden">
                  <div className="h-full w-[60%] bg-orange-500"></div>
              </div>
          </Card>

          <Card className="flex flex-col justify-between">
               <h3 className="text-sm text-slate-400 font-semibold uppercase">Quick Actions</h3>
               <div className="flex gap-2 mt-4">
                   <Button onClick={handleGenerateReport} isLoading={isGenerating} size="sm" className="flex-1">
                       Generate Summary
                   </Button>
                   <Button variant="outline" size="sm" className="flex-1">
                       Audit Rules
                   </Button>
               </div>
          </Card>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6 min-h-0 flex-1">
          {/* Predictive Insights List */}
          <Card noPadding className="flex flex-col">
              <div className="p-4 border-b border-slate-800 flex justify-between items-center">
                  <h3 className="font-bold text-white flex items-center gap-2">
                      <Activity size={18} className="text-purple-500" />
                      Forecasted Risks
                  </h3>
                  <Badge variant="purple">AI Confidence: 92%</Badge>
              </div>
              <div className="p-4 space-y-4 overflow-y-auto flex-1">
                  {insights.map(insight => (
                      <div key={insight.id} className="bg-slate-800/30 border border-slate-800 rounded-lg p-4 hover:border-slate-700 transition-colors">
                          <div className="flex justify-between items-start mb-2">
                              <div>
                                  <div className="flex items-center gap-2">
                                      <span className="font-bold text-white">{insight.type.replace('_', ' ')}</span>
                                      {getTrendIcon(insight.trend)}
                                  </div>
                                  <p className="text-xs text-slate-500 mt-0.5">{insight.location}</p>
                              </div>
                              <div className="text-right">
                                  <div className={`text-xl font-bold ${getRiskColor(insight.probability)}`}>
                                      {insight.probability}%
                                  </div>
                                  <div className="text-[10px] text-slate-500 uppercase">Probability</div>
                              </div>
                          </div>
                          <p className="text-sm text-slate-300 mb-3">{insight.description}</p>
                          <div className="flex items-center gap-2 text-xs text-slate-400 bg-slate-900/50 p-2 rounded">
                              <Calendar size={12} />
                              <span>Predicted Window: <span className="text-white font-mono">{insight.timeWindow}</span></span>
                          </div>
                      </div>
                  ))}
              </div>
          </Card>

          {/* Reporting Section */}
          <Card noPadding className="flex flex-col">
              <div className="p-4 border-b border-slate-800 flex justify-between items-center">
                  <h3 className="font-bold text-white flex items-center gap-2">
                      <FileText size={18} className="text-blue-500" />
                      Reporting Suite
                  </h3>
              </div>
              <div className="p-4 overflow-y-auto flex-1">
                  <table className="w-full text-left">
                      <thead>
                          <tr className="text-xs uppercase text-slate-500 border-b border-slate-800">
                              <th className="pb-3 font-medium">Report Name</th>
                              <th className="pb-3 font-medium">Generated</th>
                              <th className="pb-3 font-medium text-right">Action</th>
                          </tr>
                      </thead>
                      <tbody className="divide-y divide-slate-800">
                          {reports.map(report => (
                              <tr key={report.id}>
                                  <td className="py-4">
                                      <div className="flex items-center gap-3">
                                          <div className={`p-2 rounded-lg ${report.status === 'GENERATING' ? 'bg-slate-800 animate-pulse' : 'bg-slate-800'}`}>
                                              {report.status === 'GENERATING' ? <RefreshCw size={16} className="animate-spin text-slate-500" /> : <FileText size={16} className="text-blue-500" />}
                                          </div>
                                          <div>
                                              <p className="text-sm font-medium text-white">{report.title}</p>
                                              <p className="text-[10px] text-slate-500 uppercase">{report.type.replace('_', ' ')}</p>
                                          </div>
                                      </div>
                                  </td>
                                  <td className="py-4 text-xs text-slate-400 font-mono">
                                      {new Date(report.generatedAt).toLocaleDateString()}
                                  </td>
                                  <td className="py-4 text-right">
                                      {report.status === 'READY' ? (
                                          <button className="text-blue-500 hover:text-blue-400 p-2 hover:bg-slate-800 rounded transition-colors">
                                              <Download size={16} />
                                          </button>
                                      ) : (
                                          <span className="text-xs text-slate-500 italic">Processing...</span>
                                      )}
                                  </td>
                              </tr>
                          ))}
                      </tbody>
                  </table>
              </div>
          </Card>
      </div>
    </div>
  );
}

import React, { useState, useEffect } from 'react';
import { Car, Clock, Plus, Trash2, ShieldCheck, ShieldAlert, AlertCircle } from 'lucide-react';
import { Button } from '../components/Button';
import { PageHeader } from '../components/PageHeader';
import { Card } from '../components/Card';
import { Badge } from '../components/Badge';
import { VehicleAccessLog, PlateRecord } from '../types';
import { getAccessLogs, getPlateDatabase, addPlateRecord, deletePlateRecord } from '../services/accessControlService';

export default function AccessControl() {
  const [logs, setLogs] = useState<VehicleAccessLog[]>([]);
  const [plates, setPlates] = useState<PlateRecord[]>([]);
  const [activeTab, setActiveTab] = useState<'logs' | 'database'>('logs');
  const [showModal, setShowModal] = useState(false);
  const [newPlate, setNewPlate] = useState<Partial<PlateRecord>>({ status: 'ALLOWED' });

  useEffect(() => {
    loadData();
    const interval = setInterval(loadData, 5000); 
    return () => clearInterval(interval);
  }, []);

  const loadData = async () => {
    const logsData = await getAccessLogs();
    const platesData = await getPlateDatabase();
    setLogs(logsData);
    setPlates(platesData);
  };

  const handleAddPlate = async (e: React.FormEvent) => {
      e.preventDefault();
      if (newPlate.plateNumber && newPlate.status) {
          await addPlateRecord({
              plateNumber: newPlate.plateNumber,
              ownerName: newPlate.ownerName || 'Unknown',
              status: newPlate.status as any,
              vehicleType: newPlate.vehicleType || 'Car',
              notes: newPlate.notes
          });
          setShowModal(false);
          setNewPlate({ status: 'ALLOWED' });
          loadData();
      }
  };

  const handleDeletePlate = async (plate: string) => {
      if (confirm('Remove this plate from database?')) {
          await deletePlateRecord(plate);
          loadData();
      }
  };

  return (
    <div className="h-full flex flex-col space-y-6">
      <PageHeader 
        title="Vehicle Access Control"
        description="LPR Monitoring and Gate Security Logs."
        icon={Car}
        actions={
          <div className="bg-slate-900 p-1 rounded-lg border border-slate-800 flex">
            <button 
                onClick={() => setActiveTab('logs')}
                className={`px-4 py-2 rounded-md text-sm font-medium transition-colors ${activeTab === 'logs' ? 'bg-slate-800 text-white shadow-sm' : 'text-slate-400 hover:text-white'}`}
            >
                Live Logs
            </button>
            <button 
                onClick={() => setActiveTab('database')}
                className={`px-4 py-2 rounded-md text-sm font-medium transition-colors ${activeTab === 'database' ? 'bg-slate-800 text-white shadow-sm' : 'text-slate-400 hover:text-white'}`}
            >
                Plate Database
            </button>
          </div>
        }
      />

      {activeTab === 'logs' && (
          <>
            {/* KPI Stats */}
            <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                <Card className="p-6">
                    <p className="text-slate-400 text-xs uppercase font-semibold mb-1">Vehicles Today</p>
                    <p className="text-3xl font-bold text-white">{logs.length + 42}</p>
                </Card>
                <Card className="p-6">
                    <p className="text-slate-400 text-xs uppercase font-semibold mb-1">Denied / Blocked</p>
                    <p className="text-3xl font-bold text-red-500">{logs.filter(l => l.status === 'DENIED').length}</p>
                </Card>
                <Card className="p-6">
                    <p className="text-slate-400 text-xs uppercase font-semibold mb-1">Avg Dwell Time</p>
                    <p className="text-3xl font-bold text-blue-500">4m 12s</p>
                </Card>
            </div>

            {/* Logs Table */}
            <Card noPadding className="flex-1 flex flex-col min-h-0">
                <div className="p-4 border-b border-slate-800 flex items-center gap-2">
                    <Clock size={16} className="text-slate-500" />
                    <span className="text-sm font-semibold text-white">Recent Entries & Exits</span>
                </div>
                <div className="overflow-auto flex-1">
                    <table className="w-full text-left">
                        <thead className="sticky top-0 bg-slate-900 z-10">
                            <tr className="bg-slate-800/50 text-slate-400 text-xs uppercase">
                                <th className="px-6 py-3 font-medium">Timestamp</th>
                                <th className="px-6 py-3 font-medium">Plate Number</th>
                                <th className="px-6 py-3 font-medium">Status</th>
                                <th className="px-6 py-3 font-medium">Stream</th>
                                <th className="px-6 py-3 font-medium">Confidence</th>
                                <th className="px-6 py-3 font-medium text-right">Evidence</th>
                            </tr>
                        </thead>
                        <tbody className="divide-y divide-slate-800">
                            {logs.map(log => (
                                <tr key={log.id} className="hover:bg-slate-800/30 transition-colors">
                                    <td className="px-6 py-4 text-slate-300 text-sm font-mono">
                                        {new Date(log.timestamp).toLocaleTimeString()} <span className="text-slate-500 text-xs">{new Date(log.timestamp).toLocaleDateString()}</span>
                                    </td>
                                    <td className="px-6 py-4">
                                        <div className="bg-white text-black font-mono font-bold px-2 py-0.5 rounded border-2 border-slate-300 text-sm shadow-sm inline-block">
                                            {log.plateNumber}
                                        </div>
                                    </td>
                                    <td className="px-6 py-4">
                                        <Badge 
                                          variant={log.status === 'GRANTED' ? 'success' : log.status === 'DENIED' ? 'danger' : 'warning'}
                                          icon={log.status === 'GRANTED' ? <ShieldCheck size={12} /> : log.status === 'DENIED' ? <ShieldAlert size={12} /> : <AlertCircle size={12} />}
                                        >
                                            {log.status}
                                        </Badge>
                                    </td>
                                    <td className="px-6 py-4 text-slate-400 text-sm">Camera #{log.streamId}</td>
                                    <td className="px-6 py-4 text-slate-400 text-sm">{Math.round(log.confidence * 100)}%</td>
                                    <td className="px-6 py-4 text-right">
                                        {log.thumbnailUrl && (
                                            <img src={log.thumbnailUrl} alt="Plate" className="h-8 w-14 object-cover rounded bg-black inline-block border border-slate-700 hover:scale-150 transition-transform origin-right" />
                                        )}
                                    </td>
                                </tr>
                            ))}
                        </tbody>
                    </table>
                </div>
            </Card>
          </>
      )}

      {activeTab === 'database' && (
          <div className="space-y-4">
               <div className="flex justify-end">
                   <Button onClick={() => setShowModal(true)} size="sm" className="flex items-center gap-2">
                       <Plus size={16} /> Add Plate
                   </Button>
               </div>

               <Card noPadding>
                    <div className="overflow-x-auto">
                        <table className="w-full text-left">
                            <thead>
                                <tr className="bg-slate-800/50 text-slate-400 text-xs uppercase">
                                    <th className="px-6 py-3 font-medium">Plate Number</th>
                                    <th className="px-6 py-3 font-medium">Registered Owner</th>
                                    <th className="px-6 py-3 font-medium">Vehicle</th>
                                    <th className="px-6 py-3 font-medium">Access Level</th>
                                    <th className="px-6 py-3 font-medium">Notes</th>
                                    <th className="px-6 py-3 font-medium text-right">Actions</th>
                                </tr>
                            </thead>
                            <tbody className="divide-y divide-slate-800">
                                {plates.map(plate => (
                                    <tr key={plate.plateNumber} className="hover:bg-slate-800/30 transition-colors">
                                        <td className="px-6 py-4">
                                            <div className="bg-white text-black font-mono font-bold px-2 py-0.5 rounded border-2 border-slate-300 text-sm shadow-sm inline-block">
                                                {plate.plateNumber}
                                            </div>
                                        </td>
                                        <td className="px-6 py-4 text-white font-medium">{plate.ownerName}</td>
                                        <td className="px-6 py-4 text-slate-400 text-sm">{plate.vehicleType}</td>
                                        <td className="px-6 py-4">
                                            <Badge variant={plate.status === 'ALLOWED' ? 'success' : 'danger'}>
                                                {plate.status}
                                            </Badge>
                                        </td>
                                        <td className="px-6 py-4 text-slate-500 text-xs italic">{plate.notes || '-'}</td>
                                        <td className="px-6 py-4 text-right">
                                            <button 
                                                onClick={() => handleDeletePlate(plate.plateNumber)}
                                                className="text-slate-500 hover:text-red-400 transition-colors p-1"
                                            >
                                                <Trash2 size={16} />
                                            </button>
                                        </td>
                                    </tr>
                                ))}
                            </tbody>
                        </table>
                    </div>
               </Card>
          </div>
      )}

      {/* Add Modal */}
      {showModal && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4">
            <div className="absolute inset-0 bg-black/70 backdrop-blur-sm" onClick={() => setShowModal(false)} />
            <div className="relative bg-slate-900 border border-slate-800 rounded-xl w-full max-w-md shadow-2xl animate-in fade-in zoom-in duration-200">
                <div className="p-6 border-b border-slate-800">
                    <h2 className="text-xl font-bold text-white">Register Vehicle</h2>
                </div>
                <form onSubmit={handleAddPlate} className="p-6 space-y-4">
                    <div>
                        <label className="block text-xs font-medium text-slate-400 uppercase mb-1">Plate Number</label>
                        <input 
                            type="text" 
                            className="w-full bg-slate-950 border border-slate-800 rounded-lg px-3 py-2 text-white font-mono uppercase focus:ring-2 focus:ring-blue-600 outline-none"
                            required
                            value={newPlate.plateNumber || ''}
                            onChange={e => setNewPlate({...newPlate, plateNumber: e.target.value.toUpperCase()})}
                            placeholder="ABC-1234"
                        />
                    </div>
                    {/* ... other inputs simplified for brevity but functionally identical ... */}
                    <div>
                        <label className="block text-xs font-medium text-slate-400 uppercase mb-1">Owner Name</label>
                        <input 
                            type="text" 
                            className="w-full bg-slate-950 border border-slate-800 rounded-lg px-3 py-2 text-white focus:ring-2 focus:ring-blue-600 outline-none"
                            value={newPlate.ownerName || ''}
                            onChange={e => setNewPlate({...newPlate, ownerName: e.target.value})}
                        />
                    </div>
                    <div>
                        <label className="block text-xs font-medium text-slate-400 uppercase mb-1">Status</label>
                        <select 
                            className="w-full bg-slate-950 border border-slate-800 rounded-lg px-3 py-2 text-white focus:ring-2 focus:ring-blue-600 outline-none"
                            value={newPlate.status}
                            onChange={e => setNewPlate({...newPlate, status: e.target.value as any})}
                        >
                            <option value="ALLOWED">Allowed (Grant Access)</option>
                            <option value="BLOCKED">Blocked (Deny Access)</option>
                        </select>
                    </div>
                     <div>
                        <label className="block text-xs font-medium text-slate-400 uppercase mb-1">Vehicle Type</label>
                        <input 
                            type="text" 
                            className="w-full bg-slate-950 border border-slate-800 rounded-lg px-3 py-2 text-white focus:ring-2 focus:ring-blue-600 outline-none"
                            value={newPlate.vehicleType || ''}
                            onChange={e => setNewPlate({...newPlate, vehicleType: e.target.value})}
                            placeholder="e.g. Sedan, Truck"
                        />
                    </div>
                    <div className="flex justify-end gap-3 pt-2">
                        <Button type="button" variant="outline" onClick={() => setShowModal(false)}>Cancel</Button>
                        <Button type="submit">Register Plate</Button>
                    </div>
                </form>
            </div>
        </div>
      )}
    </div>
  );
}

import React, { useState } from 'react';
import { Smartphone, QrCode, ShieldCheck, Trash2, Apple, MonitorSmartphone } from 'lucide-react';
import { Button } from '../components/Button';
import { PageHeader } from '../components/PageHeader';
import { Card } from '../components/Card';
import { MobileDevice } from '../types';
import { logAction } from '../services/auditService';

export default function MobileApp() {
  const [showQr, setShowQr] = useState(false);
  const [devices, setDevices] = useState<MobileDevice[]>([
      { id: 'dev_1', name: "Chief Security's iPad", os: 'iOS', appVersion: '2.1.0', lastActive: Date.now() - 3600000, status: 'AUTHORIZED', ownerEmail: 'chief@sentinel.ai' }
  ]);

  const handleGeneratePairingCode = async () => {
      setShowQr(true);
      await logAction('DEVICE_PAIRING', 'Mobile App', 'Generated pairing QR code.');
  };

  const handleRevoke = async (id: string) => {
      if (confirm("Revoke access for this device? It will be logged out immediately.")) {
          setDevices(devices.filter(d => d.id !== id));
          await logAction('DEVICE_PAIRING', 'Revoked Device', `ID: ${id}`);
      }
  };

  return (
    <div className="h-full flex flex-col space-y-6">
      <PageHeader 
        title="Mobile Companion"
        description="Download the SentinelAI mobile app for field operations and manage authorized devices."
