      />

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
          {/* Download & Pair Card */}
          <Card className="flex flex-col items-center text-center p-8">
              <div className="w-16 h-16 bg-blue-600/20 rounded-2xl flex items-center justify-center text-blue-500 mb-6">
                  <MonitorSmartphone size={32} />
              </div>

              <h2 className="text-xl font-bold text-white mb-2">Get the App</h2>
              <p className="text-slate-400 text-sm max-w-sm mb-8">
                  Access live streams, receive push notifications for critical alerts, and perform LPR scans directly from your mobile device.
              </p>

              <div className="flex gap-4 mb-8">
                  <button className="flex items-center gap-3 bg-white text-black px-4 py-2 rounded-lg hover:bg-slate-200 transition-colors">
                      <Apple size={20} />
                      <div className="text-left">
                          <div className="text-[10px] font-bold uppercase leading-none">Download on the</div>
                          <div className="text-sm font-bold leading-none">App Store</div>
                      </div>
                  </button>
                  <button className="flex items-center gap-3 bg-slate-800 text-white border border-slate-700 px-4 py-2 rounded-lg hover:bg-slate-700 transition-colors">
                       <div className="text-left">
                          <div className="text-[10px] font-bold uppercase leading-none">Get it on</div>
                          <div className="text-sm font-bold leading-none">Google Play</div>
                      </div>
                  </button>
              </div>

              <div className="w-full border-t border-slate-800 pt-8">
                  <h3 className="text-white font-bold mb-4">Pair New Device</h3>
                  {showQr ? (
                      <div className="flex flex-col items-center animate-in zoom-in duration-300">
                          <div className="bg-white p-4 rounded-xl shadow-lg mb-4">
                              <div className="w-48 h-48 bg-white flex flex-wrap content-start">
                                  {Array.from({length: 64}).map((_, i) => (
                                      <div key={i} className={`w-6 h-6 ${Math.random() > 0.5 ? 'bg-black' : 'bg-white'}`}></div>
                                  ))}
                              </div>
                          </div>
                          <p className="text-xs text-slate-500 mb-4">Scan with the SentinelAI App</p>
                          <p className="text-xs font-mono text-yellow-500 bg-yellow-900/20 px-2 py-1 rounded">Expires in 04:59</p>
                          <Button variant="outline" size="sm" className="mt-4" onClick={() => setShowQr(false)}>Cancel</Button>
                      </div>
                  ) : (
                      <Button onClick={handleGeneratePairingCode} className="flex items-center gap-2">
                          <QrCode size={18} />
                          Generate Pairing QR Code
                      </Button>
                  )}
              </div>
          </Card>

          {/* Authorized Devices List */}
          <Card noPadding className="flex flex-col">
              <div className="p-6 border-b border-slate-800">
                  <h3 className="font-bold text-white flex items-center gap-2">
                      <ShieldCheck size={18} className="text-green-500" />
                      Authorized Devices
                  </h3>
              </div>
              <div className="flex-1 p-6 overflow-y-auto">
                  {devices.length === 0 ? (
                      <div className="text-center text-slate-500 py-10">No devices paired.</div>
                  ) : (
                      <div className="space-y-4">
                          {devices.map(device => (
                              <div key={device.id} className="flex items-center justify-between bg-slate-800/50 p-4 rounded-lg border border-slate-700">
                                  <div className="flex items-center gap-4">
                                      <div className="w-10 h-10 rounded-lg bg-slate-700 flex items-center justify-center text-slate-400">
                                          {device.os === 'iOS' ? <Apple size={20} /> : <Smartphone size={20} />}
                                      </div>
                                      <div>
                                          <h4 className="font-bold text-white text-sm">{device.name}</h4>
                                          <div className="flex items-center gap-2 text-xs text-slate-400">
                                              <span>v{device.appVersion}</span>
                                              <span>•</span>
                                              <span>{new Date(device.lastActive).toLocaleDateString()}</span>
                                          </div>
                                          <p className="text-[10px] text-slate-500 mt-0.5">{device.ownerEmail}</p>
                                      </div>
                                  </div>
                                  <button onClick={() => handleRevoke(device.id)} className="text-slate-500 hover:text-red-500 transition-colors p-2" title="Revoke Access">
                                      <Trash2 size={16} />
                                  </button>
                              </div>
                          ))}
                      </div>
                  )}
              </div>
          </Card>
      </div>
    </div>
  );
}

import React, { useState, useEffect, useRef } from 'react';
import { Map as MapIcon, ZoomIn, ZoomOut, Layers, Video, X, Maximize2, Thermometer } from 'lucide-react';
import { PageHeader } from '../components/PageHeader';
import { MapZone, CameraStream, SecurityAlert, HeatmapPoint } from '../types';
import { getZones, getStreamsByZone } from '../services/mapService';
import { getHeatmapData } from '../services/analyticsService';
import { StreamPlayer } from '../components/StreamPlayer';

export default function Geospatial() {
  const [zones, setZones] = useState<MapZone[]>([]);
  const [activeZone, setActiveZone] = useState<MapZone | null>(null);
  const [streams, setStreams] = useState<CameraStream[]>([]);
  const [zoomLevel, setZoomLevel] = useState(1);
  const [selectedStream, setSelectedStream] = useState<CameraStream | null>(null);
  const [showHeatmap, setShowHeatmap] = useState(false);
  const [heatmapData, setHeatmapData] = useState<HeatmapPoint[]>([]);

  const canvasRef = useRef<HTMLCanvasElement>(null);

  useEffect(() => {
    loadInitialData();
  }, []);

  useEffect(() => {
    if (activeZone) {
      loadStreams(activeZone.id);
      if (showHeatmap) {
          loadHeatmap(activeZone.id);
      }
    }
  }, [activeZone]);

  useEffect(() => {
      if (showHeatmap && activeZone) {
          loadHeatmap(activeZone.id);
      }
  }, [showHeatmap]);

  // Draw Heatmap
  useEffect(() => {
      if (!canvasRef.current || !showHeatmap || heatmapData.length === 0) return;

      const canvas = canvasRef.current;
      const ctx = canvas.getContext('2d');
      if (!ctx) return;

      // Clear previous
      ctx.clearRect(0, 0, canvas.width, canvas.height);

      // Draw points
      heatmapData.forEach(point => {
          const x = (point.x / 100) * canvas.width;
          const y = (point.y / 100) * canvas.height;
          const radius = 60; 

          const gradient = ctx.createRadialGradient(x, y, 0, x, y, radius);
          gradient.addColorStop(0, `rgba(255, 0, 0, ${point.intensity * 0.6})`);
          gradient.addColorStop(0.5, `rgba(255, 165, 0, ${point.intensity * 0.3})`);
          gradient.addColorStop(1, 'rgba(0, 0, 0, 0)');

          ctx.fillStyle = gradient;
          ctx.beginPath();
          ctx.arc(x, y, radius, 0, Math.PI * 2);
          ctx.fill();
      });

  }, [heatmapData, showHeatmap, zoomLevel]);

  const loadInitialData = async () => {
    const zonesData = await getZones();
    setZones(zonesData);
    if (zonesData.length > 0) setActiveZone(zonesData[0]);
  };

  const loadStreams = async (zoneId: string) => {
    const streamsData = await getStreamsByZone(zoneId);
    setStreams(streamsData);
  };

  const loadHeatmap = async (zoneId: string) => {
      const data = await getHeatmapData(zoneId);
      setHeatmapData(data);
  };

  const handleZoom = (delta: number) => {
    setZoomLevel(prev => Math.min(Math.max(prev + delta, 1), 3));
  };

  const handleAlert = (alert: SecurityAlert) => {
    console.log("Alert from map view:", alert);
  };

  return (
    <div className="h-full flex flex-col space-y-4">
      <PageHeader 
        title="Geospatial View"
        description="Interactive camera map and zone management."
        icon={MapIcon}
        actions={
          <div className="flex gap-4">
            <button 
                onClick={() => setShowHeatmap(!showHeatmap)}
                className={`flex items-center gap-2 px-3 py-1.5 rounded-lg border transition-colors ${showHeatmap ? 'bg-orange-900/50 border-orange-500 text-orange-200' : 'bg-slate-900 border-slate-800 text-slate-400 hover:text-white'}`}
            >
                <Thermometer size={16} />
                <span className="text-sm font-medium">Density Heatmap</span>
            </button>

            <div className="flex items-center gap-2 bg-slate-900 p-1.5 rounded-lg border border-slate-800">
                <Layers size={16} className="text-slate-500 ml-2" />
                <select 
                    className="bg-transparent text-white text-sm font-medium focus:outline-none border-none pr-8 py-1"
                    value={activeZone?.id || ''}
                    onChange={(e) => {
                        const zone = zones.find(z => z.id === e.target.value);
                        if (zone) setActiveZone(zone);
                    }}
                >
                    {zones.map(z => (
                        <option key={z.id} value={z.id} className="bg-slate-900">{z.name}</option>
                    ))}
                </select>
            </div>
        </div>
        }
      />

      {/* Map Container */}
      <div className="flex-1 bg-slate-950 border border-slate-800 rounded-xl overflow-hidden relative shadow-2xl group">
          {/* Map Controls */}
          <div className="absolute top-4 right-4 z-20 flex flex-col gap-2 bg-slate-900/90 backdrop-blur-sm p-2 rounded-lg border border-slate-700 shadow-lg">
              <button onClick={() => handleZoom(0.2)} className="p-2 text-slate-300 hover:text-white hover:bg-slate-700 rounded transition-colors" title="Zoom In">
                  <ZoomIn size={20} />
              </button>
              <div className="h-px bg-slate-700 w-full"></div>
              <button onClick={() => handleZoom(-0.2)} className="p-2 text-slate-300 hover:text-white hover:bg-slate-700 rounded transition-colors" title="Zoom Out">
                  <ZoomOut size={20} />
              </button>
              <div className="h-px bg-slate-700 w-full"></div>
              <button onClick={() => setZoomLevel(1)} className="p-2 text-slate-300 hover:text-white hover:bg-slate-700 rounded transition-colors" title="Reset">
                  <Maximize2 size={20} />
              </button>
          </div>

          {/* Map Surface */}
          <div className="w-full h-full overflow-hidden relative bg-[#0a0a0a]">
               {/* Grid Pattern Background */}
               <div 
                  className="absolute inset-0 opacity-20 pointer-events-none" 
                  style={{ backgroundImage: 'linear-gradient(#333 1px, transparent 1px), linear-gradient(90deg, #333 1px, transparent 1px)', backgroundSize: '40px 40px' }}
               />

               {activeZone && (
                   <div 
                        className="w-full h-full relative transition-transform duration-300 ease-out origin-center"
                        style={{ transform: `scale(${zoomLevel})` }}
                   >
                       {/* Map Image */}
                       <div className="absolute inset-4 md:inset-12 border-2 border-slate-800/50 rounded-lg overflow-hidden bg-slate-900">
                           <img 
                                src={activeZone.imageUrl} 
                                alt="Map" 
                                className="w-full h-full object-cover opacity-50 grayscale hover:grayscale-0 transition-all duration-700"
                           />

                           {/* Heatmap Canvas Layer */}
                           {showHeatmap && (
                               <canvas 
                                    ref={canvasRef}
                                    width={1600} 
                                    height={900}
                                    className="absolute inset-0 w-full h-full pointer-events-none opacity-70 mix-blend-screen animate-in fade-in duration-500"
                               />
                           )}
                       </div>

                       {/* Camera Markers */}
                       {!showHeatmap && streams.map(stream => (
                           <div 
                                key={stream.id}
                                className="absolute cursor-pointer transform -translate-x-1/2 -translate-y-1/2 group/marker z-10"
                                style={{ 
                                    left: `${stream.coordinates?.x || 50}%`, 
                                    top: `${stream.coordinates?.y || 50}%` 
                                }}
                                onClick={() => setSelectedStream(stream)}
                           >
                               {/* Pulse Effect */}
                               {stream.status === 'online' && (
                                   <div className="absolute inset-0 bg-green-500 rounded-full animate-ping opacity-75"></div>
                               )}

                               {/* Marker Icon */}
                               <div className={`relative w-8 h-8 rounded-full flex items-center justify-center shadow-lg border-2 transition-transform hover:scale-110 ${
                                   stream.status === 'online' 
                                     ? 'bg-slate-900 border-green-500 text-green-500' 
                                     : 'bg-slate-900 border-red-500 text-red-500'
                               }`}>
                                   <Video size={14} fill="currentColor" />
                               </div>

                               {/* Tooltip */}
                               <div className="absolute bottom-full left-1/2 -translate-x-1/2 mb-2 w-48 bg-slate-900/95 backdrop-blur-md border border-slate-700 rounded-lg p-2 shadow-xl opacity-0 group-hover/marker:opacity-100 transition-opacity pointer-events-none scale-95 group-hover/marker:scale-100 origin-bottom">
                                   <div className="relative aspect-video bg-black rounded overflow-hidden mb-1">
                                       {stream.status === 'online' ? (
                                           <div className="w-full h-full bg-slate-800 flex items-center justify-center">
                                                <span className="text-[10px] text-slate-500">Live Preview</span>
                                           </div>
                                       ) : (
                                           <div className="w-full h-full flex items-center justify-center bg-slate-950 text-slate-600 text-[10px]">Offline</div>
                                       )}
                                   </div>
                                   <p className="text-xs font-bold text-white truncate">{stream.name}</p>
                                   <p className="text-[10px] text-slate-400 truncate">{stream.location}</p>
                               </div>
                           </div>
                       ))}
                   </div>
               )}
          </div>
      </div>

      {/* Stream Modal */}
      {selectedStream && (
          <div className="fixed inset-0 z-[100] flex items-center justify-center p-4">
              <div className="absolute inset-0 bg-black/80 backdrop-blur-md" onClick={() => setSelectedStream(null)} />
              <div className="relative w-full max-w-4xl bg-slate-900 border border-slate-800 rounded-xl shadow-2xl overflow-hidden animate-in fade-in zoom-in duration-200 flex flex-col max-h-[90vh]">
                  <div className="flex justify-between items-center p-4 border-b border-slate-800 bg-slate-950">
                      <div className="flex items-center gap-3">
                          <div className={`w-2 h-2 rounded-full ${selectedStream.status === 'online' ? 'bg-green-500' : 'bg-red-500'}`}></div>
                          <div>
                              <h2 className="text-lg font-bold text-white leading-none">{selectedStream.name}</h2>
                              <p className="text-xs text-slate-500 mt-1">{selectedStream.location} • {activeZone?.name}</p>
                          </div>
                      </div>
                      <button onClick={() => setSelectedStream(null)} className="p-2 hover:bg-slate-800 rounded-full text-slate-400 hover:text-white transition-colors">
                          <X size={20} />
                      </button>
                  </div>
                  <div className="flex-1 bg-black min-h-[400px]">
                       <StreamPlayer 
                           stream={selectedStream}
                           onAlertGenerated={handleAlert}
                       />
                  </div>
              </div>
          </div>
      )}
    </div>
  );
}

import React, { useState, useEffect } from 'react';
import { Users, Plus, Search, Trash2, ShieldAlert, UserCheck, User, Briefcase } from 'lucide-react';
import { Button } from '../components/Button';
import { PageHeader } from '../components/PageHeader';
import { Badge } from '../components/Badge';
import { Card } from '../components/Card';
import { PersonIdentity, IdentityCategory } from '../types';
import { getIdentities, addIdentity, deleteIdentity } from '../services/identityService';
import { logAction } from '../services/auditService';

export default function Identities() {
  const [identities, setIdentities] = useState<PersonIdentity[]>([]);
  const [filter, setFilter] = useState('');
  const [showModal, setShowModal] = useState(false);
  const [newPerson, setNewPerson] = useState<Partial<PersonIdentity>>({
      category: 'EMPLOYEE',
      imageUrl: ''
  });

  useEffect(() => {
    loadIdentities();
  }, []);

  const loadIdentities = async () => {
    const data = await getIdentities();
    setIdentities(data);
  };

  const handleAdd = async (e: React.FormEvent) => {
    e.preventDefault();
    if (newPerson.name && newPerson.category) {
        await addIdentity({
            id: crypto.randomUUID(),
            name: newPerson.name,
            category: newPerson.category as IdentityCategory,
            imageUrl: newPerson.imageUrl || 'https://via.placeholder.com/200',
            notes: newPerson.notes
        });

        await logAction('ADD_IDENTITY', `Person: ${newPerson.name}`, `Category: ${newPerson.category}`);

        setShowModal(false);
        setNewPerson({ category: 'EMPLOYEE', imageUrl: '' });
        loadIdentities();
    }
  };

  const handleDelete = async (id: string, name: string) => {
      if (confirm('Are you sure you want to remove this identity record?')) {
          await deleteIdentity(id);
          await logAction('REMOVE_IDENTITY', `Person: ${name}`, `ID: ${id}`);
          loadIdentities();
      }
  };

  const filteredIdentities = identities.filter(p => 
      p.name.toLowerCase().includes(filter.toLowerCase()) || 
      p.category.toLowerCase().includes(filter.toLowerCase())
  );

  const getCategoryIcon = (cat: IdentityCategory) => {
      switch(cat) {
          case 'BLACKLISTED': return <ShieldAlert size={14} />;
          case 'VIP': return <UserCheck size={14} />;
          case 'CONTRACTOR': return <Briefcase size={14} />;
          default: return <User size={14} />;
      }
  };

  const getCategoryVariant = (cat: IdentityCategory) => {
      switch(cat) {
          case 'BLACKLISTED': return 'danger';
          case 'VIP': return 'purple';
          case 'CONTRACTOR': return 'orange';
          default: return 'info';
      }
  }

  return (
    <div className="h-full flex flex-col space-y-6">
      <PageHeader 
        title="Identity Management"
        description="Manage known personnel, VIPs, and security threats (Watchlist)."
        icon={Users}
        actions={
            <Button onClick={() => setShowModal(true)} className="flex items-center gap-2">
                <Plus size={16} />
                Add Identity
            </Button>
        }
      />

      {/* Filter Bar */}
      <Card noPadding className="p-4 flex items-center gap-4">
          <Search size={20} className="text-slate-500" />
          <input 
            type="text" 
            placeholder="Search by name or category..." 
            className="bg-transparent border-none focus:outline-none text-white w-full"
            value={filter}
            onChange={e => setFilter(e.target.value)}
          />
      </Card>

      {/* Grid */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6 overflow-y-auto pb-6">
          {filteredIdentities.map(person => (
              <Card key={person.id} noPadding className="overflow-hidden group hover:border-slate-700 transition-all shadow-lg">
                  <div className="relative h-48 bg-slate-950">
                      <img src={person.imageUrl} alt={person.name} className="w-full h-full object-cover opacity-90 group-hover:opacity-100 transition-opacity" />
                      <div className="absolute inset-0 bg-gradient-to-t from-slate-900 to-transparent"></div>
                      <div className="absolute bottom-4 left-4 right-4">
                          <h3 className="text-lg font-bold text-white truncate">{person.name}</h3>
                          <div className="mt-1">
                            <Badge variant={getCategoryVariant(person.category)} icon={getCategoryIcon(person.category)}>
                                {person.category}
                            </Badge>
                          </div>
                      </div>
                  </div>
                  <div className="p-4 space-y-3">
                      <div className="text-xs text-slate-400">
                          <span className="font-semibold text-slate-500 uppercase block mb-0.5">Notes</span>
                          {person.notes || 'No notes available.'}
                      </div>
                      <div className="text-xs text-slate-400">
                          <span className="font-semibold text-slate-500 uppercase block mb-0.5">Last Seen</span>
                          {person.lastSeen ? new Date(person.lastSeen).toLocaleString() : 'Never'}
                      </div>
                      <div className="pt-2 flex justify-end">
                          <button 
                            onClick={() => handleDelete(person.id, person.name)}
                            className="p-2 text-slate-500 hover:text-red-400 hover:bg-red-900/20 rounded transition-colors"
                          >
                              <Trash2 size={16} />
                          </button>
                      </div>
                  </div>
              </Card>
          ))}
      </div>

      {/* Add Modal */}
      {showModal && (
          <div className="fixed inset-0 z-[100] flex items-center justify-center p-4">
              <div className="absolute inset-0 bg-black/70 backdrop-blur-sm" onClick={() => setShowModal(false)} />
              <div className="relative bg-slate-900 border border-slate-800 rounded-xl w-full max-w-md shadow-2xl overflow-hidden animate-in fade-in zoom-in duration-200">
                  <div className="p-6 border-b border-slate-800">
                      <h2 className="text-xl font-bold text-white">Enroll New Identity</h2>
                  </div>
                  <form onSubmit={handleAdd} className="p-6 space-y-4">
                      <div>
                          <label className="block text-xs font-medium text-slate-400 uppercase mb-1">Full Name</label>
                          <input 
                             type="text" 
                             className="w-full bg-slate-950 border border-slate-800 rounded-lg px-3 py-2 text-white focus:ring-2 focus:ring-blue-600 outline-none"
                             required
                             value={newPerson.name || ''}
                             onChange={e => setNewPerson({...newPerson, name: e.target.value})}
                          />
                      </div>
                      <div>
                          <label className="block text-xs font-medium text-slate-400 uppercase mb-1">Category</label>
                          <select 
                             className="w-full bg-slate-950 border border-slate-800 rounded-lg px-3 py-2 text-white focus:ring-2 focus:ring-blue-600 outline-none"
                             value={newPerson.category}
                             onChange={e => setNewPerson({...newPerson, category: e.target.value as IdentityCategory})}
                          >
                              <option value="EMPLOYEE">Employee</option>
                              <option value="VIP">VIP</option>
                              <option value="CONTRACTOR">Contractor</option>
                              <option value="BLACKLISTED">Blacklisted (Threat)</option>
                          </select>
                      </div>
                      <div>
                          <label className="block text-xs font-medium text-slate-400 uppercase mb-1">Photo URL</label>
                          <input 
                             type="url" 
                             placeholder="https://..."
                             className="w-full bg-slate-950 border border-slate-800 rounded-lg px-3 py-2 text-white focus:ring-2 focus:ring-blue-600 outline-none"
                             value={newPerson.imageUrl || ''}
                             onChange={e => setNewPerson({...newPerson, imageUrl: e.target.value})}
                          />
                      </div>
                      <div>
                          <label className="block text-xs font-medium text-slate-400 uppercase mb-1">Notes</label>
                          <textarea 
                             className="w-full bg-slate-950 border border-slate-800 rounded-lg px-3 py-2 text-white focus:ring-2 focus:ring-blue-600 outline-none h-20 resize-none"
                             value={newPerson.notes || ''}
                             onChange={e => setNewPerson({...newPerson, notes: e.target.value})}
                          />
                      </div>
                      <div className="flex justify-end gap-3 pt-2">
                          <Button type="button" variant="outline" onClick={() => setShowModal(false)}>Cancel</Button>
                          <Button type="submit">Enroll Identity</Button>
                      </div>
                  </form>
              </div>
          </div>
      )}
    </div>
  );
}

import React, { useState } from 'react';
import { Search, Clock, Filter, PlayCircle, Calendar } from 'lucide-react';
import { Button } from '../components/Button';
import { PageHeader } from '../components/PageHeader';
import { Badge } from '../components/Badge';
import { Card } from '../components/Card';
import { ArchiveEvent } from '../types';
import { searchArchive } from '../services/searchService';

export default function ArchiveSearch() {
  const [query, setQuery] = useState('');
  const [isSearching, setIsSearching] = useState(false);
  const [results, setResults] = useState<ArchiveEvent[]>([]);
  const [hasSearched, setHasSearched] = useState(false);

  const handleSearch = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!query.trim()) return;

    setIsSearching(true);
    try {
      const data = await searchArchive(query);
      setResults(data);
      setHasSearched(true);
    } catch (error) {
      console.error(error);
    } finally {
      setIsSearching(false);
    }
  };

  return (
    <div className="h-full flex flex-col space-y-6">
      <PageHeader 
        title="Smart Archive Search"
        description={
            <span className="flex items-center gap-2">
                Use natural language to find specific events across your entire video retention history.
                <Badge variant="purple">Beta</Badge>
            </span>
        }
        icon={Search}
      />

      {/* Search Input Area */}
      <Card className="shadow-xl">
        <form onSubmit={handleSearch} className="space-y-4">
          <div className="relative">
             <input 
                type="text" 
                className="w-full bg-slate-950 border border-slate-700 rounded-lg py-4 pl-5 pr-12 text-lg text-white placeholder-slate-500 focus:outline-none focus:ring-2 focus:ring-blue-600 transition-all shadow-inner"
                placeholder="Describe what you are looking for (e.g., 'Person wearing red jacket', 'White truck at loading dock')"
                value={query}
                onChange={e => setQuery(e.target.value)}
             />
             <div className="absolute right-3 top-3">
                 <Button type="submit" isLoading={isSearching} disabled={!query.trim()}>
                    Search
                 </Button>
             </div>
          </div>

          <div className="flex flex-wrap gap-4 text-sm text-slate-400">
            <div className="flex items-center gap-2 bg-slate-800/50 px-3 py-1.5 rounded-full border border-slate-700 cursor-pointer hover:bg-slate-800">
                <Calendar size={14} />
                <span>Last 24 Hours</span>
            </div>
            <div className="flex items-center gap-2 bg-slate-800/50 px-3 py-1.5 rounded-full border border-slate-700 cursor-pointer hover:bg-slate-800">
                <Filter size={14} />
                <span>Min Confidence: 70%</span>
            </div>
             <div className="flex-1"></div>
             <span className="text-xs text-slate-600 pt-2">Powered by pgvector & Gemini Embeddings</span>
          </div>
        </form>
      </Card>

      {/* Results Area */}
      <div className="flex-1 min-h-0 overflow-y-auto">
        {!hasSearched && (
            <div className="h-full flex flex-col items-center justify-center text-slate-500 opacity-50">
                <Search size={64} strokeWidth={1} className="mb-4" />
                <p>Enter a description to search the video archive.</p>
            </div>
        )}

        {hasSearched && results.length === 0 && (
            <div className="h-full flex flex-col items-center justify-center text-slate-500">
                <p>No matching events found in the selected timeframe.</p>
                <Button variant="outline" className="mt-4" onClick={() => setQuery('')}>Clear Search</Button>
            </div>
        )}

        {results.length > 0 && (
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6 pb-6">
                {results.map(evt => (
                    <Card key={evt.id} noPadding className="group hover:border-blue-500/50 transition-all hover:shadow-lg hover:shadow-blue-900/10">
                        <div className="relative aspect-video bg-black">
                            <img src={evt.thumbnailUrl} alt="Thumbnail" className="w-full h-full object-cover opacity-80 group-hover:opacity-100 transition-opacity" />

                            {/* Confidence Badge */}
                            <div className="absolute top-2 right-2 bg-black/70 backdrop-blur-md text-white text-xs font-bold px-2 py-1 rounded border border-white/10">
                                {Math.round(evt.confidence * 100)}% Match
                            </div>

                            {/* Play Overlay */}
                            <div className="absolute inset-0 flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity bg-black/40">
                                <PlayCircle size={48} className="text-white drop-shadow-lg transform scale-90 group-hover:scale-100 transition-transform" />
                            </div>
                        </div>

                        <div className="p-4">
                            <div className="flex justify-between items-start mb-2">
                                <h3 className="text-sm font-semibold text-white">{evt.streamName}</h3>
                                <div className="flex items-center text-xs text-slate-500">
                                    <Clock size={12} className="mr-1" />
                                    {new Date(evt.timestamp).toLocaleString()}
                                </div>
                            </div>
                            <p className="text-xs text-slate-400 line-clamp-2 leading-relaxed">
                                {evt.description}
                            </p>
                            <div className="mt-3 flex flex-wrap gap-1">
                                {evt.tags.map(tag => (
                                    <span key={tag} className="text-[10px] bg-slate-800 text-slate-300 px-1.5 py-0.5 rounded">#{tag}</span>
                                ))}
                            </div>
                        </div>
                    </Card>
